// src/components/NotificationBell.tsx

import { useEffect, useState, useRef } from "react";
import { apiClient } from "../api/apiClient";
import { useNavigate } from "react-router-dom";
import { useAuthStore } from "../stores/authStore";

type Notification = {
  id: number;
  title: string;
  message: string;
  link?: string;
  isRead: boolean;
  createdAt: string;
};

// أيقونة الجرس (SVG)
function BellIcon({ className }: { className?: string }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
    >
      <path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9" />
      <path d="M10.3 21a1.94 1.94 0 0 0 3.4 0" />
    </svg>
  );
}

export function NotificationBell() {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();
  const user = useAuthStore((s) => s.user);

  // جلب الإشعارات
  const fetchNotifications = async () => {
    if (!user) return;
    try {
      const res = await apiClient.get<Notification[]>("/notifications");
      setNotifications(res.data);
      setUnreadCount(res.data.filter((n) => !n.isRead).length);
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    } catch (err) {
      console.error("Failed to fetch notifications");
    }
  };

  // Poll كل 60 ثانية
  useEffect(() => {
    if (user) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      fetchNotifications();
      const interval = setInterval(fetchNotifications, 60000);
      return () => clearInterval(interval);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);

  // إغلاق القائمة عند النقر خارجها
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleRead = async (n: Notification) => {
    if (!n.isRead) {
      try {
        await apiClient.patch(`/notifications/${n.id}/read`);
        setUnreadCount((prev) => Math.max(0, prev - 1));
        setNotifications((prev) =>
          prev.map((item) =>
            item.id === n.id ? { ...item, isRead: true } : item,
          ),
        );
      } catch (e) {
        console.error(e);
      }
    }

    if (n.link) {
      setIsOpen(false);
      navigate(n.link);
    }
  };

  const handleMarkAllRead = async () => {
    try {
      await apiClient.patch("/notifications/read-all");
      setNotifications((prev) => prev.map((n) => ({ ...n, isRead: true })));
      setUnreadCount(0);
    } catch (e) {
      console.error(e);
    }
  };

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="relative p-2 rounded-full hover:bg-slate-800 text-slate-300 hover:text-white transition-colors"
      >
        <BellIcon className="w-6 h-6" />
        {unreadCount > 0 && (
          <span className="absolute top-1 right-1 flex h-4 w-4 items-center justify-center rounded-full bg-rose-500 text-[10px] font-bold text-white shadow-sm ring-1 ring-slate-900">
            {unreadCount > 9 ? "+9" : unreadCount}
          </span>
        )}
      </button>

      {isOpen && (
        <div className="absolute left-0 mt-2 w-80 max-h-[400px] overflow-hidden rounded-xl border border-slate-700 bg-slate-900 shadow-2xl z-50 origin-top-left animate-in fade-in zoom-in-95 duration-100">
          <div className="flex items-center justify-between border-b border-slate-800 px-4 py-3 bg-slate-950/50">
            <h3 className="text-sm font-semibold text-white">الإشعارات</h3>
            {unreadCount > 0 && (
              <button
                onClick={handleMarkAllRead}
                className="text-xs text-sky-400 hover:text-sky-300"
              >
                تحديد الكل كمقروء
              </button>
            )}
          </div>

          <div className="overflow-y-auto max-h-[300px] scrollbar-thin scrollbar-thumb-slate-700">
            {notifications.length === 0 ? (
              <div className="py-8 text-center text-xs text-slate-500">
                لا توجد إشعارات جديدة
              </div>
            ) : (
              <div className="divide-y divide-slate-800/50">
                {notifications.map((n) => (
                  <div
                    key={n.id}
                    onClick={() => handleRead(n)}
                    className={`cursor-pointer px-4 py-3 transition-colors hover:bg-slate-800/50 ${
                      !n.isRead ? "bg-slate-800/20" : ""
                    }`}
                  >
                    <div className="flex justify-between items-start mb-1">
                      <p
                        className={`text-sm font-medium ${!n.isRead ? "text-sky-300" : "text-slate-300"}`}
                      >
                        {n.title}
                      </p>
                      {!n.isRead && (
                        <span className="h-2 w-2 rounded-full bg-sky-500 mt-1" />
                      )}
                    </div>
                    <p className="text-xs text-slate-400 line-clamp-2 leading-relaxed">
                      {n.message}
                    </p>
                    <p className="mt-2 text-[10px] text-slate-600 text-right font-mono">
                      {new Date(n.createdAt).toLocaleTimeString("ar-LY", {
                        hour: "2-digit",
                        minute: "2-digit",
                      })}
                    </p>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="border-t border-slate-800 bg-slate-950/30 px-4 py-2 text-center">
            <span className="text-[10px] text-slate-600">
              يتم تحديث الإشعارات تلقائياً
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

// src/components/clinical/MedicalHistoryForm.tsx
// =====================================================================
// التاريخ المرضي الشامل — Medical History (EMR Core)
// PMH + Surgical + Family + Social — في تبويبات فرعية
// =====================================================================

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiClient } from "../../api/apiClient";
import { toast } from "sonner";

type HistorySection = "PMH" | "SURGICAL" | "FAMILY" | "SOCIAL";

const FAMILY_RELATIONS: Record<string, string> = {
  FATHER: "الأب",
  MOTHER: "الأم",
  BROTHER: "الأخ",
  SISTER: "الأخت",
  SON: "الابن",
  DAUGHTER: "الابنة",
  GRANDFATHER: "الجد",
  GRANDMOTHER: "الجدة",
  UNCLE: "العم/الخال",
  AUNT: "العمة/الخالة",
  OTHER: "أخرى",
};

const SMOKING_OPTIONS: Record<string, string> = {
  NEVER: "لم يدخن أبداً",
  FORMER: "مدخن سابق",
  CURRENT: "مدخن حالياً",
  UNKNOWN: "غير معروف",
};

export function MedicalHistoryForm({ patientId }: { patientId: number }) {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const queryClient = useQueryClient();
  const [section, setSection] = useState<HistorySection>("PMH");

  const { data: history, isLoading } = useQuery({
    queryKey: ["patient-medical-history", patientId],
    queryFn: async () => {
      const res = await apiClient.get(`/patients/${patientId}/medical-history`);
      return res.data;
    },
  });

  if (isLoading) {
    return <div className="text-center py-8 text-slate-500 text-sm">جارِ التحميل...</div>;
  }

  const sections: { key: HistorySection; label: string; icon: string; count?: number }[] = [
    { key: "PMH", label: "الأمراض السابقة", icon: "🏥", count: history?.pastMedical?.length },
    { key: "SURGICAL", label: "العمليات الجراحية", icon: "🔪", count: history?.pastSurgical?.length },
    { key: "FAMILY", label: "التاريخ العائلي", icon: "👨‍👩‍👧‍👦", count: history?.familyHistory?.length },
    { key: "SOCIAL", label: "التاريخ الاجتماعي", icon: "🏡" },
  ];

  return (
    <div className="max-w-4xl space-y-5">
      <h2 className="text-lg font-bold text-white flex items-center gap-2">
        📖 التاريخ المرضي الشامل (Medical History)
      </h2>

      {/* Section Tabs */}
      <div className="flex gap-2 flex-wrap">
        {sections.map((s) => (
          <button
            key={s.key}
            onClick={() => setSection(s.key)}
            className={`px-4 py-2 rounded-xl text-xs font-medium transition-colors flex items-center gap-2 ${
              section === s.key
                ? "bg-sky-600 text-white"
                : "bg-slate-800 text-slate-400 hover:text-white"
            }`}
          >
            <span>{s.icon}</span>
            {s.label}
            {s.count !== undefined && s.count > 0 && (
              <span className="bg-white/20 px-1.5 py-0.5 rounded-full text-[10px]">{s.count}</span>
            )}
          </button>
        ))}
      </div>

      {/* Content */}
      {section === "PMH" && <PMHSection patientId={patientId} entries={history?.pastMedical || []} />}
      {section === "SURGICAL" && <SurgicalSection patientId={patientId} entries={history?.pastSurgical || []} />}
      {section === "FAMILY" && <FamilySection patientId={patientId} entries={history?.familyHistory || []} />}
      {section === "SOCIAL" && <SocialSection patientId={patientId} data={history?.socialHistory} />}
    </div>
  );
}

// ==================== PMH Section ====================

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function PMHSection({ patientId, entries }: { patientId: number; entries: any[] }) {
  const queryClient = useQueryClient();
  const [condition, setCondition] = useState("");
  const [year, setYear] = useState("");
  const [notes, setNotes] = useState("");

  const addMutation = useMutation({
    mutationFn: () =>
      apiClient.post(`/patients/${patientId}/pmh-entries`, {
        condition,
        diagnosisYear: year ? parseInt(year) : undefined,
        notes: notes || undefined,
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["patient-medical-history", patientId] });
      toast.success("تمت الإضافة");
      setCondition("");
      setYear("");
      setNotes("");
    },
    onError: () => toast.error("فشل في الإضافة"),
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) => apiClient.delete(`/patients/${patientId}/pmh-entries/${id}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["patient-medical-history", patientId] });
      toast.success("تم الحذف");
    },
  });

  return (
    <div className="space-y-4">
      {/* Add Form */}
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-4">
        <h4 className="text-xs text-sky-400 font-bold mb-3">➕ إضافة مرض سابق</h4>
        <div className="flex gap-3 items-end flex-wrap">
          <div className="flex-1 min-w-[200px]">
            <label className="text-[10px] text-slate-500 block mb-1">المرض / الحالة *</label>
            <input
              className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
              placeholder="مثال: ارتفاع ضغط الدم"
              value={condition}
              onChange={(e) => setCondition(e.target.value)}
            />
          </div>
          <div className="w-24">
            <label className="text-[10px] text-slate-500 block mb-1">السنة</label>
            <input
              type="number"
              className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
              placeholder="2020"
              value={year}
              onChange={(e) => setYear(e.target.value)}
              min="1900"
              max="2100"
            />
          </div>
          <div className="flex-1 min-w-[150px]">
            <label className="text-[10px] text-slate-500 block mb-1">ملاحظات</label>
            <input
              className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
              placeholder="ملاحظات اختيارية"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
            />
          </div>
          <button
            onClick={() => addMutation.mutate()}
            disabled={!condition.trim() || addMutation.isPending}
            className="px-4 py-2 bg-sky-600 hover:bg-sky-500 text-white rounded-xl text-xs font-bold disabled:opacity-50"
          >
            + أضف
          </button>
        </div>
      </div>

      {/* Entries List */}
      {entries.length === 0 ? (
        <p className="text-slate-500 text-center text-sm py-6">لا توجد أمراض سابقة مسجّلة</p>
      ) : (
        <div className="space-y-2">
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          {entries.map((e: any) => (
            <div key={e.id} className="bg-slate-900/60 border border-slate-800 rounded-xl px-4 py-3 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <span className={`w-2 h-2 rounded-full ${e.isActive ? "bg-red-500" : "bg-slate-500"}`} />
                <span className="text-sm text-slate-200">{e.condition}</span>
                {e.diagnosisYear && <span className="text-xs text-slate-500">({e.diagnosisYear})</span>}
                {e.notes && <span className="text-[10px] text-slate-500 italic">— {e.notes}</span>}
              </div>
              <button
                onClick={() => deleteMutation.mutate(e.id)}
                className="text-slate-600 hover:text-red-400 text-xs transition-colors"
              >
                🗑
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ==================== Surgical Section ====================

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function SurgicalSection({ patientId, entries }: { patientId: number; entries: any[] }) {
  const queryClient = useQueryClient();
  const [procedure, setProcedure] = useState("");
  const [year, setYear] = useState("");
  const [hospital, setHospital] = useState("");

  const addMutation = useMutation({
    mutationFn: () =>
      apiClient.post(`/patients/${patientId}/surgical-entries`, {
        procedure,
        surgeryYear: year ? parseInt(year) : undefined,
        hospitalName: hospital || undefined,
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["patient-medical-history", patientId] });
      toast.success("تمت الإضافة");
      setProcedure("");
      setYear("");
      setHospital("");
    },
    onError: () => toast.error("فشل في الإضافة"),
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) => apiClient.delete(`/patients/${patientId}/surgical-entries/${id}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["patient-medical-history", patientId] });
      toast.success("تم الحذف");
    },
  });

  return (
    <div className="space-y-4">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-4">
        <h4 className="text-xs text-sky-400 font-bold mb-3">➕ إضافة عملية جراحية</h4>
        <div className="flex gap-3 items-end flex-wrap">
          <div className="flex-1 min-w-[200px]">
            <label className="text-[10px] text-slate-500 block mb-1">اسم العملية *</label>
            <input
              className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
              placeholder="مثال: استئصال المرارة"
              value={procedure}
              onChange={(e) => setProcedure(e.target.value)}
            />
          </div>
          <div className="w-24">
            <label className="text-[10px] text-slate-500 block mb-1">السنة</label>
            <input
              type="number"
              className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
              placeholder="2020"
              value={year}
              onChange={(e) => setYear(e.target.value)}
            />
          </div>
          <div className="flex-1 min-w-[150px]">
            <label className="text-[10px] text-slate-500 block mb-1">المستشفى</label>
            <input
              className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
              placeholder="اسم المؤسسة (إن كانت خارجية)"
              value={hospital}
              onChange={(e) => setHospital(e.target.value)}
            />
          </div>
          <button
            onClick={() => addMutation.mutate()}
            disabled={!procedure.trim() || addMutation.isPending}
            className="px-4 py-2 bg-sky-600 hover:bg-sky-500 text-white rounded-xl text-xs font-bold disabled:opacity-50"
          >
            + أضف
          </button>
        </div>
      </div>

      {entries.length === 0 ? (
        <p className="text-slate-500 text-center text-sm py-6">لا توجد عمليات جراحية مسجّلة</p>
      ) : (
        <div className="space-y-2">
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          {entries.map((e: any) => (
            <div key={e.id} className="bg-slate-900/60 border border-slate-800 rounded-xl px-4 py-3 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <span className="text-base">🔪</span>
                <span className="text-sm text-slate-200">{e.procedure}</span>
                {e.surgeryYear && <span className="text-xs text-slate-500">({e.surgeryYear})</span>}
                {e.hospitalName && <span className="text-[10px] text-slate-500">— {e.hospitalName}</span>}
              </div>
              <button onClick={() => deleteMutation.mutate(e.id)} className="text-slate-600 hover:text-red-400 text-xs transition-colors">🗑</button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ==================== Family Section ====================

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function FamilySection({ patientId, entries }: { patientId: number; entries: any[] }) {
  const queryClient = useQueryClient();
  const [relation, setRelation] = useState("FATHER");
  const [condition, setCondition] = useState("");
  const [ageOfOnset, setAgeOfOnset] = useState("");
  const [isDeceased, setIsDeceased] = useState(false);

  const addMutation = useMutation({
    mutationFn: () =>
      apiClient.post(`/patients/${patientId}/family-history`, {
        relation,
        condition,
        ageOfOnset: ageOfOnset ? parseInt(ageOfOnset) : undefined,
        isDeceased,
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["patient-medical-history", patientId] });
      toast.success("تمت الإضافة");
      setCondition("");
      setAgeOfOnset("");
      setIsDeceased(false);
    },
    onError: () => toast.error("فشل في الإضافة"),
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) => apiClient.delete(`/patients/${patientId}/family-history/${id}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["patient-medical-history", patientId] });
      toast.success("تم الحذف");
    },
  });

  return (
    <div className="space-y-4">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-4">
        <h4 className="text-xs text-sky-400 font-bold mb-3">➕ إضافة تاريخ عائلي</h4>
        <div className="flex gap-3 items-end flex-wrap">
          <div className="w-36">
            <label className="text-[10px] text-slate-500 block mb-1">صلة القرابة *</label>
            <select
              className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
              value={relation}
              onChange={(e) => setRelation(e.target.value)}
            >
              {Object.entries(FAMILY_RELATIONS).map(([k, v]) => (
                <option key={k} value={k}>{v}</option>
              ))}
            </select>
          </div>
          <div className="flex-1 min-w-[200px]">
            <label className="text-[10px] text-slate-500 block mb-1">المرض / الحالة *</label>
            <input
              className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
              placeholder="مثال: سكري، ضغط، سرطان..."
              value={condition}
              onChange={(e) => setCondition(e.target.value)}
            />
          </div>
          <div className="w-20">
            <label className="text-[10px] text-slate-500 block mb-1">عمر الظهور</label>
            <input
              type="number"
              className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
              placeholder="45"
              value={ageOfOnset}
              onChange={(e) => setAgeOfOnset(e.target.value)}
            />
          </div>
          <div className="flex items-center gap-2 pb-1">
            <input type="checkbox" id="deceased" checked={isDeceased} onChange={(e) => setIsDeceased(e.target.checked)} />
            <label htmlFor="deceased" className="text-[10px] text-slate-400">متوفى</label>
          </div>
          <button
            onClick={() => addMutation.mutate()}
            disabled={!condition.trim() || addMutation.isPending}
            className="px-4 py-2 bg-sky-600 hover:bg-sky-500 text-white rounded-xl text-xs font-bold disabled:opacity-50"
          >
            + أضف
          </button>
        </div>
      </div>

      {entries.length === 0 ? (
        <p className="text-slate-500 text-center text-sm py-6">لا يوجد تاريخ عائلي مسجّل</p>
      ) : (
        <div className="space-y-2">
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          {entries.map((e: any) => (
            <div key={e.id} className="bg-slate-900/60 border border-slate-800 rounded-xl px-4 py-3 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <span className="text-xs bg-slate-800 px-2 py-1 rounded font-bold text-slate-300">{FAMILY_RELATIONS[e.relation] || e.relation}</span>
                <span className="text-sm text-slate-200">{e.condition}</span>
                {e.ageOfOnset && <span className="text-xs text-slate-500">(ظهر في عمر {e.ageOfOnset})</span>}
                {e.isDeceased && <span className="text-[10px] text-red-400 bg-red-500/10 px-1.5 py-0.5 rounded">متوفى</span>}
              </div>
              <button onClick={() => deleteMutation.mutate(e.id)} className="text-slate-600 hover:text-red-400 text-xs transition-colors">🗑</button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ==================== Social Section ====================

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function SocialSection({ patientId, data }: { patientId: number; data: any }) {
  const queryClient = useQueryClient();
  const [smokingStatus, setSmokingStatus] = useState(data?.smokingStatus || "");
  const [occupation, setOccupation] = useState(data?.occupation || "");
  const [exerciseLevel, setExerciseLevel] = useState(data?.exerciseLevel || "");
  const [dietNotes, setDietNotes] = useState(data?.dietNotes || "");
  const [socialNotes, setSocialNotes] = useState(data?.socialNotes || "");
  const [mobilityStatus, setMobilityStatus] = useState(data?.mobilityStatus || "");

  const saveMutation = useMutation({
    mutationFn: () =>
      apiClient.put(`/patients/${patientId}/medical-history`, {
        smokingStatus: smokingStatus || undefined,
        occupation: occupation || undefined,
        exerciseLevel: exerciseLevel || undefined,
        dietNotes: dietNotes || undefined,
        socialNotes: socialNotes || undefined,
        mobilityStatus: mobilityStatus || undefined,
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["patient-medical-history", patientId] });
      queryClient.invalidateQueries({ queryKey: ["patient-chart", patientId] });
      toast.success("تم حفظ التاريخ الاجتماعي");
    },
    onError: () => toast.error("فشل في الحفظ"),
  });

  return (
    <div className="bg-slate-900 border border-slate-800 rounded-2xl p-5 max-w-2xl space-y-5">
      <h4 className="text-sm text-sky-400 font-bold">🏡 التاريخ الاجتماعي والوظيفي</h4>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="text-xs text-slate-400 block mb-1">حالة التدخين</label>
          <select
            className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
            value={smokingStatus}
            onChange={(e) => setSmokingStatus(e.target.value)}
          >
            <option value="">— غير محدد —</option>
            {Object.entries(SMOKING_OPTIONS).map(([k, v]) => (
              <option key={k} value={k}>{v}</option>
            ))}
          </select>
        </div>

        <div>
          <label className="text-xs text-slate-400 block mb-1">المهنة</label>
          <input
            className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
            placeholder="الوظيفة / المهنة"
            value={occupation}
            onChange={(e) => setOccupation(e.target.value)}
          />
        </div>

        <div>
          <label className="text-xs text-slate-400 block mb-1">مستوى النشاط البدني</label>
          <select
            className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
            value={exerciseLevel}
            onChange={(e) => setExerciseLevel(e.target.value)}
          >
            <option value="">— غير محدد —</option>
            <option value="SEDENTARY">خامل (لا يمارس رياضة)</option>
            <option value="LIGHT">خفيف (1-2 مرات/أسبوع)</option>
            <option value="MODERATE">معتدل (3-4 مرات/أسبوع)</option>
            <option value="ACTIVE">نشط (5+ مرات/أسبوع)</option>
          </select>
        </div>

        <div>
          <label className="text-xs text-slate-400 block mb-1">الحالة الحركية</label>
          <select
            className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
            value={mobilityStatus}
            onChange={(e) => setMobilityStatus(e.target.value)}
          >
            <option value="">— غير محدد —</option>
            <option value="INDEPENDENT">مستقل تماماً</option>
            <option value="ASSISTED">يحتاج مساعدة جزئية</option>
            <option value="WHEELCHAIR">كرسي متحرك</option>
            <option value="BEDRIDDEN">طريح الفراش</option>
          </select>
        </div>

        <div className="md:col-span-2">
          <label className="text-xs text-slate-400 block mb-1">ملاحظات غذائية</label>
          <input
            className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500"
            placeholder="حمية خاصة، قيود غذائية..."
            value={dietNotes}
            onChange={(e) => setDietNotes(e.target.value)}
          />
        </div>

        <div className="md:col-span-2">
          <label className="text-xs text-slate-400 block mb-1">ملاحظات اجتماعية أخرى</label>
          <textarea
            className="w-full bg-slate-950 border border-slate-700 rounded-xl px-3 py-2 text-sm outline-none focus:border-sky-500 min-h-[60px]"
            placeholder="أي ملاحظات اجتماعية إضافية..."
            value={socialNotes}
            onChange={(e) => setSocialNotes(e.target.value)}
          />
        </div>
      </div>

      <div className="flex justify-end pt-2">
        <button
          onClick={() => saveMutation.mutate()}
          disabled={saveMutation.isPending}
          className="px-6 py-2 bg-sky-600 hover:bg-sky-500 text-white rounded-xl text-xs font-bold disabled:opacity-50 transition-colors"
        >
          {saveMutation.isPending ? "جارِ الحفظ..." : "💾 حفظ التغييرات"}
        </button>
      </div>
    </div>
  );
}

// src/components/encounter/PrescriptionsTab.tsx

import { useEffect, useState } from "react";
import { apiClient } from "../../api/apiClient";
import { toast } from "sonner";

// --- Types ---
type MedicationRoute =
  | "ORAL"
  | "IV"
  | "IM"
  | "SC"
  | "TOPICAL"
  | "INHALATION"
  | "OTHER";
type MedicationFrequency =
  | "ONCE"
  | "BID"
  | "TID"
  | "QID"
  | "QHS"
  | "PRN"
  | "DAILY"
  | "OTHER";

type ProductItemLite = {
  id: number;
  code?: string | null;
  name: string;
  genericName?: string | null;
  strength?: string | null;
  form?: string | null;
  stockOnHand: number;
};

type PrescriptionDto = {
  id: number;
  createdAt: string;
  doctor?: { fullName: string };
  status: string;
  notes?: string | null;
  items: {
    id: number;
    drugItem: ProductItemLite; // Note: mapped from product in backend
    dose: string;
    route: string;
    frequency: string;
    durationDays: number;
    quantity: number;
    notes?: string | null;
  }[];
};

type DraftItem = {
  tempId: number;
  drugItemId?: number;
  dose: string;
  route: MedicationRoute;
  frequency: MedicationFrequency;
  durationDays: number;
  quantity: number;
  notes?: string;
};

type PrescriptionsTabProps = {
  encounterId: number;
  hospitalId: number;
  doctorId?: number | null;
};

const ROUTE_OPTIONS = [
  { value: "ORAL", label: "فموي" },
  { value: "IV", label: "وريدي" },
  { value: "IM", label: "عضلي" },
  { value: "SC", label: "تحت الجلد" },
  { value: "TOPICAL", label: "موضعي" },
  { value: "INHALATION", label: "استنشاق" },
  { value: "OTHER", label: "أخرى" },
];

const FREQ_OPTIONS = [
  { value: "ONCE", label: "مرة واحدة" },
  { value: "BID", label: "مرتان يومياً" },
  { value: "TID", label: "3 مرات يومياً" },
  { value: "QID", label: "4 مرات يومياً" },
  { value: "DAILY", label: "مرة يومياً" },
  { value: "QHS", label: "قبل النوم" },
  { value: "PRN", label: "عند اللزوم" },
];

export function PrescriptionsTab({
  encounterId,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  hospitalId,
  doctorId,
}: PrescriptionsTabProps) {
  const [catalog, setCatalog] = useState<ProductItemLite[]>([]);
  const [prescriptions, setPrescriptions] = useState<PrescriptionDto[]>([]);

  // Initial Draft State
  const [items, setItems] = useState<DraftItem[]>([
    {
      tempId: 1,
      drugItemId: undefined,
      dose: "",
      route: "ORAL",
      frequency: "BID",
      durationDays: 3,
      quantity: 1,
      notes: "",
    },
  ]);
  const [nextTempId, setNextTempId] = useState(2);
  const [globalNotes, setGlobalNotes] = useState("");

  const canOrder = !!doctorId;

  useEffect(() => {
    const load = async () => {
      try {
        const [resP, resC] = await Promise.all([
          apiClient.get<PrescriptionDto[]>(
            `/pharmacy/encounters/${encounterId}/prescriptions`,
          ),
          apiClient.get<ProductItemLite[]>(`/pharmacy/catalog`),
        ]);
        setPrescriptions(resP.data);
        setCatalog(resC.data);
      } catch (e) {
        console.error(e);
      }
    };
    if (encounterId) load();
  }, [encounterId]);

  // Form Handlers
  const addRow = () => {
    setItems((prev) => [
      ...prev,
      {
        tempId: nextTempId,
        drugItemId: undefined,
        dose: "",
        route: "ORAL",
        frequency: "BID",
        durationDays: 3,
        quantity: 1,
        notes: "",
      },
    ]);
    setNextTempId((n) => n + 1);
  };

  const removeRow = (id: number) => {
    setItems((prev) =>
      prev.length > 1 ? prev.filter((i) => i.tempId !== id) : prev,
    );
  };

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const updateItem = (id: number, field: keyof DraftItem, val: any) => {
    setItems((prev) =>
      prev.map((i) => (i.tempId === id ? { ...i, [field]: val } : i)),
    );
  };

  const submitPrescription = async () => {
    if (!canOrder) {
      toast.error("لا يمكن إنشاء وصفة. يرجى تعيين طبيب للحالة أولاً.");
      return;
    }

    // Validation
    const validItems = items.filter((i) => i.drugItemId);
    if (validItems.length === 0) {
      toast.warning("أضف دواء واحداً على الأقل.");
      return;
    }

    try {
      await apiClient.post(
        `/pharmacy/encounters/${encounterId}/prescriptions`,
        {
          doctorId,
          notes: globalNotes || undefined,
          items: validItems.map((it) => ({
            drugItemId: it.drugItemId,
            dose: it.dose || "As directed",
            route: it.route,
            frequency: it.frequency,
            durationDays: Number(it.durationDays),
            quantity: Number(it.quantity),
            notes: it.notes,
          })),
        },
      );
      toast.success("تم حفظ الوصفة");
      // Reset
      setItems([
        {
          tempId: 1,
          drugItemId: undefined,
          dose: "",
          route: "ORAL",
          frequency: "BID",
          durationDays: 3,
          quantity: 1,
          notes: "",
        },
      ]);
      setGlobalNotes("");

      // Reload list
      const res = await apiClient.get<PrescriptionDto[]>(
        `/pharmacy/encounters/${encounterId}/prescriptions`,
      );
      setPrescriptions(res.data);
      setPrescriptions(res.data);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (e: any) {
      // ✅ معالجة تحذيرات السلامة
      if (e.response?.data?.code === "SAFETY_WARNING") {
        const warnings = e.response.data.interactions
          .map(
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (w: any) =>
              `- ${w.drugs.join(" + ")}: ${w.description} (${w.severity})`,
          )
          .join("\n");

        if (
          confirm(
            `⚠️ تحذير للتداخلات الدوائية:\n${warnings}\n\nهل تريد تجاوز التحذير ومتابعة الوصفة؟`,
          )
        ) {
          // إعادة المحاولة مع override
          try {
            await apiClient.post(
              `/pharmacy/encounters/${encounterId}/prescriptions`,
              {
                doctorId,
                notes: globalNotes || undefined,
                overrideSafety: true, // 👈 إرسال طلب التجاوز
                items: validItems.map((it) => ({
                  drugItemId: it.drugItemId,
                  dose: it.dose || "As directed",
                  route: it.route,
                  frequency: it.frequency,
                  durationDays: Number(it.durationDays),
                  quantity: Number(it.quantity),
                  notes: it.notes,
                })),
              },
            );
            toast.success("تم حفظ الوصفة (مع تجاوز التحذيرات)");
            // Reset & Reload
            setItems([
              {
                tempId: 1,
                drugItemId: undefined,
                dose: "",
                route: "ORAL",
                frequency: "BID",
                durationDays: 3,
                quantity: 1,
                notes: "",
              },
            ]);
            setGlobalNotes("");
            const res = await apiClient.get<PrescriptionDto[]>(
              `/pharmacy/encounters/${encounterId}/prescriptions`,
            );
            setPrescriptions(res.data);
            return;
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          } catch (retryErr: any) {
             toast.error(retryErr.response?.data?.message || "فشل الحفظ بعد التجاوز");
             return;
          }
        }
      }
      toast.error(e.response?.data?.message || "فشل الحفظ");
    }
  };

  const renderDrugName = (d: ProductItemLite) => {
    return `${d.name} ${d.strength ? d.strength : ""} ${d.form ? `(${d.form})` : ""}`;
  };

  return (
    <div className="space-y-6">
      {/* Form Area */}
      <div
        className={`border border-slate-800 rounded-2xl p-4 bg-slate-900/60 shadow-sm ${!canOrder ? "opacity-60 pointer-events-none grayscale" : ""}`}
      >
        <div className="flex justify-between items-center mb-3 pb-2 border-b border-slate-800/50">
          <h3 className="font-semibold text-sm text-slate-200">
            وصفة طبية جديدة
          </h3>
          {!canOrder && (
            <span className="text-[10px] text-rose-300 font-bold bg-rose-950/40 px-2 py-1 rounded">
              ⛔ يجب تعيين طبيب أولاً
            </span>
          )}
        </div>

        {/* Dynamic Rows */}
        <div className="space-y-2">
          // eslint-disable-next-line @typescript-eslint/no-unused-vars
          {items.map((item, idx) => (
            <div
              key={item.tempId}
              className="flex flex-col md:flex-row gap-2 items-start bg-slate-950/50 p-2 rounded-xl border border-slate-800/50"
            >
              <div className="flex-1 min-w-[200px]">
                <label className="text-[10px] text-slate-500 mb-1 block">
                  الدواء
                </label>
                <select
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-2 py-1.5 text-xs outline-none focus:border-emerald-500"
                  value={item.drugItemId ?? ""}
                  onChange={(e) =>
                    updateItem(
                      item.tempId,
                      "drugItemId",
                      Number(e.target.value),
                    )
                  }
                >
                  <option value="">-- اختر الدواء --</option>
                  {catalog.map((d) => (
                    <option key={d.id} value={d.id}>
                      {renderDrugName(d)} (رصيد: {d.stockOnHand})
                    </option>
                  ))}
                </select>
              </div>

              <div className="w-24">
                <label className="text-[10px] text-slate-500 mb-1 block">
                  الجرعة
                </label>
                <input
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-2 py-1.5 text-xs outline-none focus:border-emerald-500"
                  placeholder="500mg"
                  value={item.dose}
                  onChange={(e) =>
                    updateItem(item.tempId, "dose", e.target.value)
                  }
                />
              </div>

              <div className="w-28">
                <label className="text-[10px] text-slate-500 mb-1 block">
                  الطريق
                </label>
                <select
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-2 py-1.5 text-xs outline-none focus:border-emerald-500"
                  value={item.route}
                  onChange={(e) =>
                    updateItem(item.tempId, "route", e.target.value)
                  }
                >
                  {ROUTE_OPTIONS.map((o) => (
                    <option key={o.value} value={o.value}>
                      {o.label}
                    </option>
                  ))}
                </select>
              </div>

              <div className="w-28">
                <label className="text-[10px] text-slate-500 mb-1 block">
                  التكرار
                </label>
                <select
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-2 py-1.5 text-xs outline-none focus:border-emerald-500"
                  value={item.frequency}
                  onChange={(e) =>
                    updateItem(item.tempId, "frequency", e.target.value)
                  }
                >
                  {FREQ_OPTIONS.map((o) => (
                    <option key={o.value} value={o.value}>
                      {o.label}
                    </option>
                  ))}
                </select>
              </div>

              <div className="w-16">
                <label className="text-[10px] text-slate-500 mb-1 block">
                  المدة (يوم)
                </label>
                <input
                  type="number"
                  min="1"
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-2 py-1.5 text-xs text-center outline-none focus:border-emerald-500"
                  value={item.durationDays}
                  onChange={(e) =>
                    updateItem(item.tempId, "durationDays", e.target.value)
                  }
                />
              </div>

              <div className="w-16">
                <label className="text-[10px] text-slate-500 mb-1 block">
                  الكمية
                </label>
                <input
                  type="number"
                  min="1"
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-2 py-1.5 text-xs text-center font-bold text-emerald-400 outline-none focus:border-emerald-500"
                  value={item.quantity}
                  onChange={(e) =>
                    updateItem(item.tempId, "quantity", e.target.value)
                  }
                />
              </div>

              <button
                onClick={() => removeRow(item.tempId)}
                className="mt-6 p-1.5 text-slate-500 hover:text-rose-400 transition"
                title="حذف السطر"
              >
                ✕
              </button>
            </div>
          ))}
        </div>

        <button
          onClick={addRow}
          className="mt-2 text-xs text-sky-400 hover:text-sky-300 font-medium px-2 py-1 hover:bg-sky-950/30 rounded transition"
        >
          + إضافة دواء آخر
        </button>

        <div className="mt-4 pt-3 border-t border-slate-800/50 flex flex-col md:flex-row gap-3 items-end">
          <div className="flex-1 w-full">
            <label className="text-[10px] text-slate-500 mb-1 block">
              ملاحظات عامة للصيدلي (اختياري)
            </label>
            <input
              className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-xs outline-none focus:border-emerald-500"
              placeholder="مثال: يصرف البديل في حال عدم التوفر..."
              value={globalNotes}
              onChange={(e) => setGlobalNotes(e.target.value)}
            />
          </div>
          <button
            onClick={submitPrescription}
            disabled={!canOrder}
            className="bg-emerald-600 hover:bg-emerald-500 text-white px-6 py-2 rounded-xl text-xs font-bold shadow-lg shadow-emerald-500/20 disabled:opacity-50 transition"
          >
            حفظ وإرسال الوصفة
          </button>
        </div>
      </div>

      {/* List Area */}
      <div className="space-y-4">
        <h3 className="text-sm font-semibold text-slate-400 px-1">
          سجل الوصفات السابقة
        </h3>
        {prescriptions.length === 0 && (
          <div className="text-center text-xs text-slate-500 py-6 border border-dashed border-slate-800 rounded-2xl">
            لا توجد وصفات مسجلة لهذه الحالة.
          </div>
        )}

        {prescriptions.map((pres) => (
          <div
            key={pres.id}
            className="bg-slate-900/40 border border-slate-800 rounded-2xl p-4"
          >
            <div className="flex justify-between items-center mb-3 pb-2 border-b border-slate-800/50">
              <div className="flex items-center gap-2">
                <span className="text-emerald-400 font-mono text-sm font-bold">
                  وصفة #{pres.id}
                </span>
                <span className="text-xs text-slate-500">
                  {new Date(pres.createdAt).toLocaleString("ar-LY")}
                </span>
              </div>
              <span className="text-[10px] bg-slate-950 px-2 py-0.5 rounded text-slate-300 border border-slate-800">
                {pres.doctor?.fullName ?? "Unknown Doctor"}
              </span>
            </div>

            <div className="space-y-2">
              {pres.items.map((it) => (
                <div
                  key={it.id}
                  className="flex justify-between items-center text-xs bg-slate-950/30 p-2 rounded-lg border border-slate-800/30"
                >
                  <div className="font-medium text-slate-200">
                    {renderDrugName(it.drugItem)}
                  </div>
                  <div className="text-slate-400 flex gap-3">
                    <span>{it.dose}</span>
                    <span className="text-slate-600">|</span>
                    <span>{it.frequency}</span>
                    <span className="text-slate-600">|</span>
                    <span>{it.durationDays} يوم</span>
                  </div>
                  <div className="font-mono text-emerald-400 font-bold bg-emerald-950/30 px-2 py-0.5 rounded">
                    {it.quantity}
                  </div>
                </div>
              ))}
            </div>
            {pres.notes && (
              <div className="mt-3 text-[11px] text-amber-200/70 bg-amber-900/10 p-2 rounded border border-amber-900/20">
                ملاحظات: {pres.notes}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

