                          ))}
                        </select>
                      )}
                    </div>
                  );
                })()}

              <p className="text-[10px] text-slate-500">
                * اختيار السرير اختياري. يمكن تعيين السرير لاحقاً من صفحة حالات
                الإيواء.
              </p>
            </div>
            <div className="flex justify-end gap-2">
              <button
                onClick={() => setShowAdmitModal(false)}
                className="px-4 py-2 bg-slate-800 rounded-xl text-xs text-slate-300"
              >
                إلغاء
              </button>
              <button
                onClick={handleAdmit}
                className="px-4 py-2 bg-purple-600 hover:bg-purple-500 rounded-xl text-xs text-white font-bold"
              >
                تأكيد الدخول
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Transfer Request Modal */}
      {encounter.patient && (
        <Suspense fallback={null}>
          <RequestTransferModal
            isOpen={showTransferModal}
            onClose={() => setShowTransferModal(false)}
            encounterId={encId}
            patientName={encounter.patient.fullName}
            fromBedId={null} // Can't easily grab bed from pure encounter query here, backend will figure it out if it exists
            onSuccess={() => {
              // Can show a toast or refresh
            }}
          />
        </Suspense>
      )}

      {/* AI Coding Suggestions Modal */}
      {showAiModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
          <div className="bg-slate-900 border border-slate-700 w-full max-w-3xl rounded-2xl shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="bg-gradient-to-r from-slate-800/80 to-indigo-900/30 p-4 border-b border-slate-700 flex justify-between items-center">
              <h2 className="text-lg font-bold text-sky-400 flex items-center gap-2">
                <Sparkles className="w-5 h-5" />
                المساعد الذكي — تحليل واعتماد الأكواد الطبية
              </h2>
              <button
                onClick={() => {
                  setShowAiModal(false);
                  setAiSuggestions(null);
                }}
                className="text-slate-400 hover:text-white transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-5 flex-1 overflow-y-auto max-h-[70vh] custom-scrollbar">
              {aiCodingMutation.isPending ? (
                <div className="flex flex-col items-center justify-center py-16 space-y-4">
                  <div className="relative">
                    <span className="h-14 w-14 animate-spin rounded-full border-4 border-slate-700 border-t-sky-500 block" />
                    <span className="absolute inset-0 flex items-center justify-center text-xl">
                      🧠
                    </span>
                  </div>
                  <p className="text-sm text-slate-400">
                    يقوم الذكاء الاصطناعي بتحليل الملاحظات واستخراج الأكواد...
                  </p>
                  <p className="text-[10px] text-slate-600">
                    ICD-10 + CPT + E&M Evaluation
                  </p>
                </div>
              ) : aiSuggestions ? (
                <div className="space-y-6">
                  {/* AI Reasoning (collapsible) */}
                  {aiSuggestions.reasoning && (
                    <details className="bg-indigo-950/30 border border-indigo-900/40 rounded-xl overflow-hidden">
                      <summary className="px-4 py-3 text-xs font-bold text-indigo-300 cursor-pointer hover:bg-indigo-900/20 transition-colors flex items-center gap-2">
                        🧠 التحليل المنطقي للذكاء الاصطناعي (Reasoning)
                      </summary>
                      <div className="px-4 pb-3 text-xs text-indigo-200/70 leading-relaxed whitespace-pre-wrap border-t border-indigo-900/30 pt-3">
                        {aiSuggestions.reasoning}
                      </div>
                    </details>
                  )}

                  {/* ICD-10 Diagnoses */}
                  {aiSuggestions.diagnoses &&
                    aiSuggestions.diagnoses.length > 0 && (
                      <div>
                        <div className="flex justify-between items-center mb-3 border-b border-slate-800 pb-2">
                          <h3 className="text-sm font-bold text-emerald-400">
                            تشخيصات ICD-10 المقترحة
                          </h3>
                          <button
                            onClick={() => {
                              if (
                                selectedDxCodes.size ===
                                aiSuggestions.diagnoses.length
                              )
                                setSelectedDxCodes(new Set());
                              else
                                setSelectedDxCodes(
                                  new Set(
                                    aiSuggestions.diagnoses.map(
                                      // eslint-disable-next-line @typescript-eslint/no-explicit-any
                                      (_: any, i: number) => i,
                                    ),
                                  ),
                                );
                            }}
                            className="text-[10px] text-emerald-500 hover:text-emerald-300 font-bold transition-colors"
                          >
                            {selectedDxCodes.size ===
                            aiSuggestions.diagnoses.length
                              ? "إلغاء الكل"
                              : "تحديد الكل"}
                          </button>
                        </div>
                        <div className="space-y-2">
                          // eslint-disable-next-line
                          @typescript-eslint/no-explicit-any
                          // eslint-disable-next-line @typescript-eslint/no-explicit-any
                          {aiSuggestions.diagnoses.map((dx: any, i: number) => (
                            <label
                              key={i}
                              className={`flex items-start gap-3 bg-slate-950 border rounded-xl p-3 cursor-pointer transition-all ${
                                selectedDxCodes.has(i)
                                  ? "border-emerald-500/60 ring-1 ring-emerald-500/20"
                                  : "border-slate-800 hover:border-slate-700"
                              }`}
                            >
                              <input
                                type="checkbox"
                                checked={selectedDxCodes.has(i)}
                                onChange={() => {
                                  const next = new Set(selectedDxCodes);
                                  if (next.has(i)) {
                                    next.delete(i);
                                  } else {
                                    next.add(i);
                                  }
                                  setSelectedDxCodes(next);
                                }}
                                className="mt-1 accent-emerald-500 w-4 h-4 shrink-0"
                              />
                              <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-2 flex-wrap">
                                  <span className="font-mono text-emerald-300 font-bold bg-emerald-900/30 px-2 py-0.5 rounded text-sm">
                                    {dx.code}
                                  </span>
                                  <span className="text-sm text-slate-200 truncate">
                                    {dx.nameEn}
                                  </span>
                                  {dx.nameAr && (
                                    <span className="text-xs text-slate-500">
                                      ({dx.nameAr})
                                    </span>
                                  )}
                                </div>
                                <div className="flex items-center gap-3 mt-2">
                                  <div className="flex-1 max-w-[120px]">
                                    <div className="h-1.5 bg-slate-800 rounded-full overflow-hidden">
                                      <div
                                        className={`h-full rounded-full transition-all ${dx.confidence >= 0.8 ? "bg-emerald-500" : dx.confidence >= 0.5 ? "bg-amber-500" : "bg-red-500"}`}
                                        style={{
                                          width: `${dx.confidence * 100}%`,
                                        }}
                                      />
                                    </div>
                                    <span className="text-[9px] text-slate-600 mt-0.5 block">
                                      {Math.round(dx.confidence * 100)}% ثقة
                                    </span>
                                  </div>
                                  <select
                                    value={dxTypes[i] || "SECONDARY"}
                                    onChange={(e) =>
                                      setDxTypes({
                                        ...dxTypes,
                                        [i]: e.target.value as
                                          | "PRIMARY"
                                          | "SECONDARY",
                                      })
                                    }
                                    className="bg-slate-900 border border-slate-700 rounded-lg px-2 py-1 text-[10px] text-slate-300 outline-none focus:border-emerald-500"
                                  >
                                    <option value="PRIMARY">
                                      رئيسي (Primary)
                                    </option>
                                    <option value="SECONDARY">
                                      ثانوي (Secondary)
                                    </option>
                                  </select>
                                </div>
                              </div>
                            </label>
                          ))}
                        </div>
                      </div>
                    )}

                  {/* CPT Procedures */}
                  {aiSuggestions.procedures &&
                    aiSuggestions.procedures.length > 0 && (
                      <div>
                        <div className="flex justify-between items-center mb-3 border-b border-slate-800 pb-2">
                          <h3 className="text-sm font-bold text-amber-400">
                            إجراءات CPT المقترحة
                          </h3>
                          <button
                            onClick={() => {
                              if (
                                selectedPxCodes.size ===
                                aiSuggestions.procedures.length
                              )
                                setSelectedPxCodes(new Set());
                              else
                                setSelectedPxCodes(
                                  new Set(
                                    aiSuggestions.procedures.map(
                                      // eslint-disable-next-line @typescript-eslint/no-explicit-any
                                      (_: any, i: number) => i,
                                    ),
                                  ),
                                );
                            }}
                            className="text-[10px] text-amber-500 hover:text-amber-300 font-bold transition-colors"
                          >
                            {selectedPxCodes.size ===
                            aiSuggestions.procedures.length
                              ? "إلغاء الكل"
                              : "تحديد الكل"}
                          </button>
                        </div>
                        <div className="space-y-2">
                          // eslint-disable-next-line
                          @typescript-eslint/no-explicit-any
                          {aiSuggestions.procedures.map(
                            // eslint-disable-next-line @typescript-eslint/no-explicit-any
                            (px: any, i: number) => (
                              <label
                                key={i}
                                className={`flex items-start gap-3 bg-slate-950 border rounded-xl p-3 cursor-pointer transition-all ${
                                  selectedPxCodes.has(i)
                                    ? "border-amber-500/60 ring-1 ring-amber-500/20"
                                    : "border-slate-800 hover:border-slate-700"
                                }`}
                              >
                                <input
                                  type="checkbox"
                                  checked={selectedPxCodes.has(i)}
                                  onChange={() => {
                                    const next = new Set(selectedPxCodes);
                                    if (next.has(i)) {
                                      next.delete(i);
                                    } else {
                                      next.add(i);
                                    }
                                    setSelectedPxCodes(next);
                                  }}
                                  className="mt-1 accent-amber-500 w-4 h-4 shrink-0"
                                />
                                <div className="flex-1 min-w-0">
                                  <div className="flex items-center gap-2 flex-wrap">
                                    <span className="font-mono text-amber-300 font-bold bg-amber-900/30 px-2 py-0.5 rounded text-sm">
                                      {px.code}
                                    </span>
                                    {px.modifier && (
                                      <span className="text-[10px] text-amber-500 bg-amber-950/50 px-1.5 py-0.5 rounded font-mono">
                                        -{px.modifier}
                                      </span>
                                    )}
                                    <span className="text-sm text-slate-200 truncate">
                                      {px.nameEn}
                                    </span>
                                  </div>
                                  {px.nameAr && (
                                    <div className="text-xs text-slate-500 mt-1">
                                      {px.nameAr}
                                    </div>
                                  )}
                                  <div className="mt-2 max-w-[120px]">
                                    <div className="h-1.5 bg-slate-800 rounded-full overflow-hidden">
                                      <div
                                        className={`h-full rounded-full transition-all ${px.confidence >= 0.8 ? "bg-amber-500" : px.confidence >= 0.5 ? "bg-yellow-500" : "bg-red-500"}`}
                                        style={{
                                          width: `${px.confidence * 100}%`,
                                        }}
                                      />
                                    </div>
                                    <span className="text-[9px] text-slate-600 mt-0.5 block">
                                      {Math.round(px.confidence * 100)}% ثقة
                                    </span>
                                  </div>
                                </div>
                              </label>
                            ),
                          )}
                        </div>
                      </div>
                    )}

                  {!aiSuggestions.diagnoses?.length &&
                    !aiSuggestions.procedures?.length && (
                      <div className="text-center text-slate-500 py-8">
                        لم يتعرف الذكاء الاصطناعي على أية أكواد طبية دقيقة من
                        الملاحظات المكتوبة.
                      </div>
                    )}

                  <div className="bg-sky-950/30 border border-sky-900/50 rounded-xl p-4 text-xs text-sky-200/70 leading-relaxed">
                    <strong className="text-sky-400">ملاحظة:</strong> اختر
                    الأكواد المناسبة واضغط "اعتماد" لحفظها تلقائياً في التشخيص
                    والفوترة. الأكواد غير المرتبطة بخدمات في النظام ستظهر
                    كتنبيهات.
                  </div>
                </div>
              ) : (
                <div className="text-center text-slate-500 py-8">
                  حدث خطأ أثناء تحميل الاقتراحات.
                </div>
              )}
            </div>

            <div className="bg-slate-800/50 p-4 border-t border-slate-700 flex justify-between items-center">
              <div className="text-[10px] text-slate-500">
                {aiSuggestions && (
                  <span>
                    {selectedDxCodes.size + selectedPxCodes.size} كود مُختار
                  </span>
                )}
              </div>
              <div className="flex gap-3">
                <button
                  onClick={() => {
                    setShowAiModal(false);
                    setAiSuggestions(null);
                  }}
                  className="bg-slate-700 hover:bg-slate-600 text-white px-5 py-2 rounded-xl text-sm font-bold transition-colors"
                >
                  إغلاق
                </button>
                {aiSuggestions &&
                  (selectedDxCodes.size > 0 || selectedPxCodes.size > 0) && (
                    <button
                      onClick={() => applyCodesMutation.mutate()}
                      disabled={applyCodesMutation.isPending}
                      className="bg-gradient-to-r from-emerald-600 to-sky-600 hover:from-emerald-500 hover:to-sky-500 text-white px-6 py-2 rounded-xl text-sm font-bold transition-all shadow-lg shadow-emerald-500/20 disabled:opacity-50 flex items-center gap-2"
                    >
                      {applyCodesMutation.isPending ? (
                        <>
                          <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/30 border-t-white" />{" "}
                          جاري الاعتماد...
                        </>
                      ) : (
                        <>
                          ✅ اعتماد المختار (
                          {selectedDxCodes.size + selectedPxCodes.size})
                        </>
                      )}
                    </button>
                  )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// src/pages/IntegrationPage.tsx

import { useEffect, useState } from "react";
import { apiClient } from "../api/apiClient";
import { toast } from "sonner";

// Types
type DeviceType = "LAB" | "RADIOLOGY";

type Device = {
  id: number;
  name: string;
  type: DeviceType;
  protocol: string;
  ipAddress: string;
  port: number;
  isActive: boolean;
  _count?: { mappings: number };
};

type Mapping = {
  id: number;
  deviceTestCode: string;
  labTest: { id: number; name: string; code: string };
};

type Log = {
  id: number;
  direction: "INBOUND" | "OUTBOUND";
  messageType: string;
  rawMessage: string;
  status: string;
  createdAt: string;
  device: { name: string };
};

type LabTestLite = { id: number; name: string; code: string };

export default function IntegrationPage() {
  const [activeTab, setActiveTab] = useState<"DEVICES" | "LOGS">("DEVICES");

  // Devices State
  const [devices, setDevices] = useState<Device[]>([]);
  const [showDeviceModal, setShowDeviceModal] = useState(false);

  // Form State for Device (Create/Edit)
  const [editingDevice, setEditingDevice] = useState<Device | null>(null);
  const [deviceForm, setDeviceForm] = useState({
    name: "",
    type: "LAB" as DeviceType,
    ipAddress: "127.0.0.1",
    port: 6661,
    isActive: true,
  });

  // Mapping State
  const [selectedDeviceId, setSelectedDeviceId] = useState<number | null>(null);
  const [mappings, setMappings] = useState<Mapping[]>([]);
  const [labTests, setLabTests] = useState<LabTestLite[]>([]);
  const [newMapping, setNewMapping] = useState({
    labTestId: "",
    deviceCode: "",
  });

  // Logs State
  const [logs, setLogs] = useState<Log[]>([]);

  // Loaders
  const loadDevices = async () => {
    try {
      const res = await apiClient.get<Device[]>("/integration/devices");
      setDevices(res.data);
    } catch {
      toast.error("فشل تحميل الأجهزة");
    }
  };

  const loadLogs = async () => {
    try {
      const res = await apiClient.get<Log[]>("/integration/logs");
      setLogs(res.data);
    } catch {
      toast.error("فشل تحميل السجلات");
    }
  };

  const loadMappings = async (devId: number) => {
    try {
      const res = await apiClient.get<Mapping[]>(
        `/integration/devices/${devId}/mappings`,
      );
      setMappings(res.data);
      // Load lab catalog for dropdown
      if (labTests.length === 0) {
        const cat = await apiClient.get<LabTestLite[]>("/lab/catalog");
        setLabTests(cat.data);
      }
    } catch {
      toast.error("فشل تحميل التعيينات");
    }
  };

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (activeTab === "DEVICES") loadDevices();
    if (activeTab === "LOGS") loadLogs();
  }, [activeTab]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (selectedDeviceId) loadMappings(selectedDeviceId);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDeviceId]);

  // Actions: Device
  const openCreateModal = () => {
    setEditingDevice(null);
    setDeviceForm({
      name: "",
      type: "LAB",
      ipAddress: "127.0.0.1",
      port: 6662,
      isActive: true,
    });
    setShowDeviceModal(true);
  };

  const openEditModal = (dev: Device) => {
    setEditingDevice(dev);
    setDeviceForm({
      name: dev.name,
      type: dev.type,
      ipAddress: dev.ipAddress,
      port: dev.port,
      isActive: dev.isActive,
    });
    setShowDeviceModal(true);
  };

  const handleSaveDevice = async () => {
    if (!deviceForm.name || !deviceForm.port) {
      toast.warning("يرجى إدخال الاسم والمنفذ");
      return;
    }

    try {
      if (editingDevice) {
        // Edit
        await apiClient.patch(
          `/integration/devices/${editingDevice.id}`,
          deviceForm,
        );
        toast.success("تم تحديث الجهاز");
      } else {
        // Create
        await apiClient.post("/integration/devices", deviceForm);
        toast.success("تم إضافة الجهاز");
      }
      setShowDeviceModal(false);
      loadDevices();
    } catch {
      toast.error("فشل الحفظ");
    }
  };

  const handleDeleteDevice = async (id: number) => {
    if (
      !confirm(
        "هل أنت متأكد من حذف هذا الجهاز؟ سيتم حذف جميع الإعدادات المرتبطة.",
      )
    )
      return;
    try {
      await apiClient.delete(`/integration/devices/${id}`);
      toast.success("تم حذف الجهاز");
      if (selectedDeviceId === id) setSelectedDeviceId(null);
      loadDevices();
    } catch {
      toast.error("فشل الحذف");
    }
  };

  // Actions: Mapping
  const handleAddMapping = async () => {
    if (!selectedDeviceId || !newMapping.labTestId || !newMapping.deviceCode)
      return;
    try {
      await apiClient.post(
        `/integration/devices/${selectedDeviceId}/mappings`,
        newMapping,
      );
      toast.success("تم الربط");
      setNewMapping({ labTestId: "", deviceCode: "" });
      loadMappings(selectedDeviceId);
      loadDevices(); // لتحديث العداد
    } catch {
      toast.error("فشل الربط (ربما موجود مسبقاً)");
    }
  };

  const handleDeleteMapping = async (mappingId: number) => {
    if (!confirm("هل أنت متأكد من إلغاء هذا الربط؟")) return;
    try {
      await apiClient.delete(`/integration/mappings/${mappingId}`);
      toast.success("تم الحذف بنجاح");
      if (selectedDeviceId) loadMappings(selectedDeviceId);
    } catch (err) {
      console.error(err);
      toast.error("فشل عملية الحذف");
    }
  };

  return (
    <div
      className="p-6 text-slate-100 h-full flex flex-col space-y-6"
      dir="rtl"
    >
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold mb-1">
            الربط والتكامل (LIS/PACS Integration)
          </h1>
          <p className="text-sm text-slate-400">
            إدارة أجهزة المختبر والأشعة وربط الأكواد ومراقبة الرسائل (HL7).
          </p>
        </div>
        <div className="flex bg-slate-800 rounded-lg p-1">
          <button
            onClick={() => setActiveTab("DEVICES")}
            className={`px-4 py-1.5 rounded-md text-sm transition ${activeTab === "DEVICES" ? "bg-slate-600 text-white shadow" : "text-slate-400 hover:text-slate-200"}`}
          >
            الأجهزة والإعدادات
          </button>
          <button
            onClick={() => setActiveTab("LOGS")}
            className={`px-4 py-1.5 rounded-md text-sm transition ${activeTab === "LOGS" ? "bg-slate-600 text-white shadow" : "text-slate-400 hover:text-slate-200"}`}
          >
            سجل الرسائل (Logs)
          </button>
        </div>
      </div>

      {activeTab === "DEVICES" && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 flex-1 min-h-0">
          {/* قائمة الأجهزة */}
          <div className="lg:col-span-1 bg-slate-900/60 border border-slate-800 rounded-2xl p-4 flex flex-col">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-semibold text-slate-200">الأجهزة المعرفة</h3>
              <button
                onClick={openCreateModal}
                className="text-xs bg-emerald-600 px-3 py-1.5 rounded-lg hover:bg-emerald-500 font-bold transition text-white"
              >
                + جديد
              </button>
            </div>

            <div className="flex-1 overflow-auto space-y-3">
              {devices.length === 0 && (
                <div className="text-center text-slate-500 text-xs py-10">
                  لا توجد أجهزة مضافة.
                </div>
              )}

              {devices.map((dev) => (
                <div
                  key={dev.id}
                  onClick={() => setSelectedDeviceId(dev.id)}
                  className={`p-4 rounded-xl border cursor-pointer transition relative group ${selectedDeviceId === dev.id ? "bg-sky-900/20 border-sky-500 shadow-md" : "bg-slate-950/50 border-slate-800 hover:border-slate-600"}`}
                >
                  <div className="flex justify-between items-start">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-sm text-slate-100">
                          {dev.name}
                        </span>
                        <span
                          className={`text-[9px] px-1.5 py-0.5 rounded border ${dev.type === "LAB" ? "bg-purple-900/30 text-purple-300 border-purple-500/30" : "bg-orange-900/30 text-orange-300 border-orange-500/30"}`}
                        >
                          {dev.type}
                        </span>
                      </div>
                      <div
                        className="text-xs text-slate-400 mt-1 font-mono"
                        dir="ltr"
                      >
                        {dev.ipAddress}:{dev.port}
                      </div>
                    </div>

                    <span
                      className={`text-[10px] px-2 py-0.5 rounded ${dev.isActive ? "bg-emerald-900/40 text-emerald-400" : "bg-rose-900/40 text-rose-400"}`}
                    >
                      {dev.isActive ? "نشط" : "متوقف"}
                    </span>
                  </div>

                  <div className="flex justify-between items-center mt-3 pt-2 border-t border-slate-800/50">
                    <span className="text-[10px] text-slate-500">
                      عدد التحاليل المربوطة: {dev._count?.mappings ?? 0}
                    </span>

                    <div className="flex gap-2">
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          openEditModal(dev);
                        }}
                        className="text-xs text-sky-400 hover:text-sky-300"
                      >
                        تعديل
                      </button>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDeleteDevice(dev.id);
                        }}
                        className="text-xs text-rose-400 hover:text-rose-300"
                      >
                        حذف
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* إعدادات المابينج للجهاز المختار */}
          <div className="lg:col-span-2 bg-slate-900/60 border border-slate-800 rounded-2xl p-4 flex flex-col">
            {!selectedDeviceId ? (
              <div className="flex-1 flex flex-col items-center justify-center text-slate-500 gap-2">
                <div className="text-4xl opacity-20">🖥️</div>
                <div>اختر جهازاً من القائمة لإدارة الأكواد الخاصة به.</div>
              </div>
            ) : (
              <>
                <h3 className="font-semibold mb-4 text-sky-400 flex items-center gap-2">
                  <span>ربط الأكواد (Code Mapping)</span>
                  <span className="text-xs text-slate-500 font-normal">
                    - {devices.find((d) => d.id === selectedDeviceId)?.name}
                  </span>
                </h3>

                {/* فورم الإضافة */}
                <div className="flex flex-wrap gap-3 mb-4 bg-slate-950 p-4 rounded-xl border border-slate-800 items-end">
                  <div className="flex-1 min-w-[200px]">
                    <label className="text-[11px] text-slate-400 block mb-1">
                      التحليل في النظام
                    </label>
                    <select
                      className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm focus:border-sky-500 outline-none"
                      value={newMapping.labTestId}
                      onChange={(e) =>
                        setNewMapping({
                          ...newMapping,
                          labTestId: e.target.value,
                        })
                      }
                    >
                      <option value="">-- اختر التحليل --</option>
                      {labTests.map((t) => (
                        <option key={t.id} value={t.id}>
                          {t.name} ({t.code})
                        </option>
                      ))}
                    </select>
                  </div>
                  <div className="w-48">
                    <label className="text-[11px] text-slate-400 block mb-1">
                      كود الجهاز (Device Code)
                    </label>
                    <input
                      className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm focus:border-sky-500 outline-none"
                      placeholder="e.g. GLU"
                      value={newMapping.deviceCode}
                      onChange={(e) =>
                        setNewMapping({
                          ...newMapping,
                          deviceCode: e.target.value,
                        })
                      }
                    />
                  </div>
                  <button
                    onClick={handleAddMapping}
                    className="bg-sky-600 hover:bg-sky-500 text-white px-6 py-2 rounded-lg text-sm font-bold shadow-lg shadow-sky-500/20"
                  >
                    ربط
                  </button>
                </div>

                {/* الجدول */}
                <div className="flex-1 overflow-auto rounded-xl border border-slate-800 bg-slate-950/30">
                  <table className="w-full text-sm text-right">
                    <thead className="text-slate-400 bg-slate-900/80 sticky top-0">
                      <tr>
                        <th className="p-3 font-medium">التحليل (System)</th>
                        <th className="p-3 font-medium">كود الجهاز (Device)</th>
                        <th className="p-3 w-20 text-center">إجراء</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800">
                      {mappings.length === 0 && (
                        <tr>
                          <td
                            colSpan={3}
                            className="p-8 text-center text-slate-500 text-xs"
                          >
                            لا توجد أكواد مربوطة لهذا الجهاز.
                          </td>
                        </tr>
                      )}
                      {mappings.map((m) => (
                        <tr
                          key={m.id}
                          className="hover:bg-slate-800/30 transition"
                        >
                          <td className="p-3 text-slate-200">
                            {m.labTest.name}
                            <span className="text-xs text-slate-500 mr-2 font-mono bg-slate-900 px-1.5 py-0.5 rounded">
                              {m.labTest.code}
                            </span>
                          </td>
                          <td className="p-3 font-mono text-emerald-400 font-bold">
                            {m.deviceTestCode}
                          </td>
                          <td className="p-3 text-center">
                            <button
                              onClick={() => handleDeleteMapping(m.id)}
                              className="text-rose-400 hover:text-rose-300 text-xs bg-rose-900/10 px-2 py-1 rounded hover:bg-rose-900/20"
                            >
                              حذف
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </>
            )}
          </div>
        </div>
      )}

      {activeTab === "LOGS" && (
        <div className="flex-1 bg-black rounded-2xl border border-slate-800 p-4 font-mono text-xs overflow-auto shadow-inner">
          <table className="w-full text-left border-collapse">
            <thead className="text-slate-500 border-b border-slate-800 bg-slate-900/50 sticky top-0">
              <tr>
                <th className="p-3 w-32">Time</th>
                <th className="p-3 w-40">Device</th>
                <th className="p-3 w-24">Dir</th>
                <th className="p-3 w-24">Type</th>
                <th className="p-3 w-24">Status</th>
                <th className="p-3">Raw Message</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-900">
              {logs.map((log) => (
                <tr
                  key={log.id}
                  className="hover:bg-slate-900 transition group"
                >
                  <td className="p-3 text-slate-400 whitespace-nowrap">
                    {new Date(log.createdAt).toLocaleTimeString()}
                  </td>
                  <td className="p-3 text-sky-300 font-semibold">
                    {log.device.name}
                  </td>
                  <td className="p-3">
                    <span
                      className={`px-2 py-0.5 rounded text-[10px] ${log.direction === "INBOUND" ? "bg-emerald-900/40 text-emerald-400" : "bg-blue-900/40 text-blue-400"}`}
                    >
                      {log.direction}
                    </span>
                  </td>
                  <td className="p-3 text-slate-300">{log.messageType}</td>
                  <td className="p-3">
                    <span
                      className={`text-[10px] ${log.status === "ERROR" ? "text-rose-500 font-bold" : "text-slate-400"}`}
                    >
                      {log.status}
                    </span>
                  </td>
                  <td className="p-3 text-slate-500 break-all group-hover:text-slate-300 transition">
                    {log.rawMessage.replace(/\r/g, "↵ ")}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal إضافة/تعديل جهاز */}
      {showDeviceModal && (
        <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-slate-950 border border-slate-700 rounded-2xl p-6 w-full max-w-sm space-y-4 shadow-2xl">
            <h3 className="font-bold text-lg text-white">
              {editingDevice ? "تعديل بيانات الجهاز" : "إضافة جهاز جديد"}
            </h3>

            <div className="space-y-3">
              <div>
                <label className="text-xs text-slate-400 block mb-1">
                  اسم الجهاز
                </label>
                <input
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-3 py-2 text-sm focus:border-sky-500 outline-none"
                  placeholder="مثال: Cobas 6000"
                  value={deviceForm.name}
                  onChange={(e) =>
                    setDeviceForm({ ...deviceForm, name: e.target.value })
                  }
                />
              </div>

              <div>
                <label className="text-xs text-slate-400 block mb-1">
                  النوع
                </label>
                <select
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl px-3 py-2 text-sm focus:border-sky-500 outline-none"
                  value={deviceForm.type}
                  onChange={(e) =>
                    setDeviceForm({
                      ...deviceForm,
                      type: e.target.value as DeviceType,
                    })
                  }
                >
                  <option value="LAB">مختبر (Lab)</option>
                  <option value="RADIOLOGY">أشعة (Radiology)</option>
                </select>
              </div>

              <div className="flex gap-3">
                <div className="flex-1">
                  <label className="text-xs text-slate-400 block mb-1">
                    IP Address
                  </label>
                  <input
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-3 py-2 text-sm font-mono text-center focus:border-sky-500 outline-none"
                    placeholder="127.0.0.1"
                    value={deviceForm.ipAddress}
                    onChange={(e) =>
                      setDeviceForm({
                        ...deviceForm,
                        ipAddress: e.target.value,
                      })
                    }
                  />
                </div>
                <div className="w-24">
                  <label className="text-xs text-slate-400 block mb-1">
                    Port
                  </label>
                  <input
                    type="number"
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl px-3 py-2 text-sm font-mono text-center focus:border-sky-500 outline-none"
                    placeholder="6661"
                    value={deviceForm.port}
                    onChange={(e) =>
                      setDeviceForm({
                        ...deviceForm,
                        port: Number(e.target.value),
                      })
                    }
                  />
                </div>
              </div>

              <div className="flex items-center gap-2 mt-2">
                <input
                  type="checkbox"
                  id="isActive"
                  checked={deviceForm.isActive}
                  onChange={(e) =>
                    setDeviceForm({ ...deviceForm, isActive: e.target.checked })
                  }
                  className="w-4 h-4 bg-slate-800 border-slate-600 rounded"
                />
                <label htmlFor="isActive" className="text-sm text-slate-300">
                  الجهاز نشط (Active)
                </label>
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-4">
              <button
                onClick={() => setShowDeviceModal(false)}
                className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl text-sm transition"
              >
                إلغاء
              </button>
              <button
                onClick={handleSaveDevice}
                className="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-sm font-bold shadow-lg shadow-emerald-500/20 transition"
              >
                حفظ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React from "react";
import { useParams } from "react-router-dom";
import { apiClient } from "../api/apiClient";
import { useQuery } from "@tanstack/react-query";
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { Loader2 } from "lucide-react";

// eslint-disable-next-line @typescript-eslint/no-unused-vars
type OrganizationSettings = {
  id: number;
  displayName: string;
  legalName: string;
  address: string;
  phone: string;
  email: string;
  logo?: string;
  taxNumber?: string;
  commercialRegister?: string;
};

// eslint-disable-next-line @typescript-eslint/no-unused-vars
type EncounterStatus = "OPEN" | "CLOSED" | "CANCELLED";
type EncounterType = "OPD" | "ER" | "IPD";

type Patient = {
  id: number;
  fullName: string;
  mrn: string;
  gender?: "MALE" | "FEMALE" | "OTHER" | null;
  dateOfBirth?: string | null;
};

type BillingPayment = {
  id: number;
  amount: string;
  method: string;
  paidAt: string;
  reference?: string | null;
};

type ServiceItemLite = {
  id: number;
  name: string;
  code?: string | null;
};

type ChargeLite = {
  id: number;
  quantity: number;
  unitPrice: string;
  totalAmount: string;
  createdAt: string;
  serviceItem: ServiceItemLite;
};

type InvoiceLite = {
  id: number;
  status: string;
  totalAmount: string;
  discountAmount: string;
  paidAmount: string;
  remainingAmount: string;
  currency: string;
  createdAt: string;
  type: string;
  originalInvoiceId?: number;
  insuranceShare?: string;
};

// eslint-disable-next-line @typescript-eslint/no-unused-vars
type InvoicePrintData = {
  invoice: InvoiceLite;
  patient: Patient;
  encounter: {
    id: number;
    type: EncounterType;
  } | null;
  charges: ChargeLite[];
  payments: BillingPayment[];
};

function formatDateTime(iso?: string | null) {
  if (!iso) return "—";
  const d = new Date(iso);
  return d.toLocaleString("ar-LY", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function formatDate(iso?: string | null) {
  if (!iso) return "—";
  const d = new Date(iso);
  return d.toLocaleDateString("ar-LY", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
}

function formatMoney(val: number | string | null | undefined) {
  const num = Number(val ?? 0);
  return num.toLocaleString("ar-LY", {
    minimumFractionDigits: 3,
    maximumFractionDigits: 3,
  });
}

export default function InvoicePrintCleanPage() {
  const { id } = useParams();
  const invoiceId = Number(id);

  // Fetch organization settings
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const { data: orgSettings, isLoading: orgLoading } = useQuery({
    queryKey: ["organizationSettings"],
    queryFn: async () => {
      try {
        const res = await apiClient.get("/settings/organization");
        console.log("Organization settings fetched:", res.data);
        return res.data;
      } catch (error) {
        console.error("Error fetching organization settings:", error);
        return null;
      }
    },
    staleTime: Infinity,
  });

  const { data, isLoading, isError, error } = useQuery({
    queryKey: ["invoicePrint", invoiceId],
    queryFn: async () => {
      if (!invoiceId) throw new Error("رقم الفاتورة غير صحيح");
      const res = await apiClient.get(`/billing/invoices/${invoiceId}/print`);
      return res.data;
    },
    enabled: !!invoiceId,
    retry: 1,
  });

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 text-rose-500 font-bold">
        <div className="text-center">جاري تحميل الفاتورة...</div>
      </div>
    );
