type ChartTab =
  | "OVERVIEW"
  | "PROBLEMS"
  | "HISTORY"
  | "HOME_MEDS"
  | "ALLERGIES"
  | "ENCOUNTERS";

const tabs: { key: ChartTab; label: string; icon: string }[] = [
