import React, { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Link } from "react-router-dom";
import {
  Calendar,
  Clock,
  MapPin,
  Plus,
  Search,
  Server,
  X,
  XCircle,
} from "lucide-react";
import { toast } from "sonner";
import { clinicalServices } from "../../../api/clinicalServices";
import { apiClient } from "../../../api/apiClient";
import { useAuthStore } from "../../../stores/authStore";

export default function ResourceSchedulerPage() {
  const { user } = useAuthStore();
  const hospitalId = user?.hospitalId || 1;
  const queryClient = useQueryClient();

  const [activeResource, setActiveResource] = useState<number | null>(null);
  const [showBookingModal, setShowBookingModal] = useState(false);
  const [showCreateResourceModal, setShowCreateResourceModal] = useState(false);
  const [resourceSearch, setResourceSearch] = useState("");

  const [patientId, setPatientId] = useState("");
  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");
  const [notes, setNotes] = useState("");

  const [resourceName, setResourceName] = useState("");
  const [resourceType, setResourceType] = useState("ROOM");
  const [resourceDepartmentId, setResourceDepartmentId] = useState("");

  const { data: resources = [], isLoading: loadingResources } = useQuery({
    queryKey: ["resources", hospitalId],
    queryFn: () => clinicalServices.getResources(hospitalId),
  });

  const { data: departments = [] } = useQuery({
    queryKey: ["resource-departments", hospitalId],
    queryFn: async () => {
      const res = await apiClient.get("/departments");
      return (res.data || []).filter(
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (dept: any) => dept.hospitalId === hospitalId && dept.isActive !== false,
      );
    },
  });

  const fromDate = new Date();
  const toDate = new Date();
  toDate.setDate(toDate.getDate() + 7);

  const { data: bookings = [], isLoading: loadingBookings, refetch: refetchBookings } =
    useQuery({
      queryKey: ["resource-bookings", activeResource],
      queryFn: () =>
        clinicalServices.getResourceBookings(
          activeResource!,
          fromDate.toISOString(),
          toDate.toISOString(),
        ),
      enabled: !!activeResource,
    });

  const bookMutation = useMutation({
    mutationFn: async () => {
      await clinicalServices.createBooking({
        resourceId: activeResource,
        title: `Patient #${patientId}${notes.trim() ? ` - ${notes.trim()}` : ""}`,
        scheduledStart: new Date(startTime).toISOString(),
        scheduledEnd: new Date(endTime).toISOString(),
      });
    },
    onSuccess: () => {
      toast.success("تم حجز المورد بنجاح.");
      setShowBookingModal(false);
      setPatientId("");
      setStartTime("");
      setEndTime("");
      setNotes("");
      refetchBookings();
    },
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    onError: (err: any) =>
      toast.error(err.response?.data?.message || "فشل الحجز أو يوجد تعارض."),
  });

  const createResourceMutation = useMutation({
    mutationFn: async () => {
      await clinicalServices.createResource({
        hospitalId,
        departmentId: resourceDepartmentId ? Number(resourceDepartmentId) : undefined,
        name: resourceName.trim(),
        type: resourceType,
      });
    },
    onSuccess: () => {
      toast.success("تمت إضافة المورد بنجاح.");
      setShowCreateResourceModal(false);
      setResourceName("");
      setResourceType("ROOM");
      setResourceDepartmentId("");
      queryClient.invalidateQueries({ queryKey: ["resources", hospitalId] });
    },
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    onError: (err: any) =>
      toast.error(err.response?.data?.message || "فشل إضافة المورد."),
  });

  const cancelMutation = useMutation({
    mutationFn: (bookingId: number) => clinicalServices.cancelBooking(bookingId),
    onSuccess: () => {
      toast.success("تم إلغاء الحجز.");
      refetchBookings();
    },
    onError: () => toast.error("فشل الإلغاء."),
  });

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const filteredResources = resources.filter((resource: any) => {
    if (!resourceSearch.trim()) return true;
    const query = resourceSearch.trim().toLowerCase();
    return (
      resource.name?.toLowerCase().includes(query) ||
      resource.type?.toLowerCase().includes(query) ||
      resource.department?.name?.toLowerCase().includes(query)
    );
  });

  return (
    <div className="flex flex-col h-full text-slate-100 p-4 md:p-6 space-y-6 overflow-hidden">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shadow-sm relative overflow-hidden">
        <div className="absolute top-0 left-0 w-64 h-64 bg-indigo-500/10 rounded-full blur-3xl pointer-events-none" />
        <div className="relative z-10">
          <h1 className="text-2xl font-bold text-white flex items-center gap-3">
            <div className="p-2 bg-indigo-500/20 text-indigo-400 rounded-xl">
              <Server className="w-6 h-6" />
            </div>
            جدولة الموارد المتقدمة
          </h1>
          <p className="text-sm text-slate-400 mt-1">
            إدارة وحجز الموارد السريرية مثل الغرف والمعدات مع منع التعارض.
          </p>
        </div>
        <div className="relative z-10 flex gap-2">
          <button
            onClick={() => setShowCreateResourceModal(true)}
            className="bg-emerald-600/20 text-emerald-400 border border-emerald-500/30 hover:bg-emerald-600/40 px-4 py-2 rounded-xl text-sm font-bold transition-colors flex items-center gap-2 shadow-lg"
          >
            <Plus className="w-4 h-4" /> إضافة مورد
          </button>
          <Link
            to="/clinical/waitlist"
            className="bg-amber-600/20 text-amber-400 border border-amber-500/30 hover:bg-amber-600/40 px-4 py-2 rounded-xl text-sm font-bold transition-colors flex items-center gap-2 shadow-lg"
          >
            <Clock className="w-4 h-4" /> قوائم الانتظار
          </Link>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-6 flex-1 overflow-hidden">
        <div className="w-full lg:w-1/3 bg-slate-900/60 border border-slate-800 rounded-2xl p-4 overflow-y-auto custom-scrollbar">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-bold text-slate-200">الموارد المتاحة</h3>
          </div>

          <div className="relative mb-4">
            <Search className="w-4 h-4 absolute right-3 top-3 text-slate-500" />
            <input
              type="text"
              placeholder="ابحث عن مورد..."
              className="w-full bg-slate-950 border border-slate-700 rounded-xl py-2 pr-9 pl-3 text-sm focus:border-indigo-500 outline-none"
              value={resourceSearch}
              onChange={(e) => setResourceSearch(e.target.value)}
            />
          </div>

          <div className="space-y-3">
            {loadingResources ? (
              <p className="text-center text-slate-500 py-4">جاري التحميل...</p>
            ) : filteredResources.length === 0 ? (
              <div className="text-center text-slate-500 py-8 border border-dashed border-slate-700 rounded-xl">
                لا توجد موارد مطابقة.
              </div>
            ) : (
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              filteredResources.map((resource: any) => (
                <button
                  key={resource.id}
                  onClick={() => setActiveResource(resource.id)}
                  className={`w-full text-right p-4 rounded-xl border transition-all ${
                    activeResource === resource.id
                      ? "bg-indigo-600/20 border-indigo-500 shadow-[0_0_15px_-3px_rgba(99,102,241,0.3)]"
                      : "bg-slate-950 border-slate-800 hover:border-slate-600"
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <div className="font-bold text-slate-200">{resource.name}</div>
                    <span className="text-[10px] px-2 py-0.5 rounded-full bg-slate-800 text-slate-400 font-mono">
                      {resource.type}
                    </span>
                  </div>
                  <div className="text-xs text-slate-500 mt-2 flex gap-3">
                    <span className="flex items-center gap-1">
                      <MapPin className="w-3 h-3" />
                      {resource.department?.name || "بدون قسم"}
                    </span>
                  </div>
                </button>
              ))
            )}
          </div>
        </div>

        <div className="w-full lg:w-2/3 bg-slate-900/40 border border-slate-800 rounded-2xl p-5 overflow-y-auto custom-scrollbar relative">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-lg font-bold text-slate-200 flex items-center gap-2">
              <Calendar className="w-5 h-5 text-indigo-400" />
              الحجوزات القادمة {activeResource ? "(7 أيام)" : ""}
            </h2>
            {activeResource && (
              <button
                onClick={() => setShowBookingModal(true)}
                className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-lg transition-colors flex items-center gap-2"
              >
                <Plus className="w-4 h-4" /> حجز المورد
              </button>
            )}
          </div>

          {!activeResource ? (
            <div className="flex flex-col items-center justify-center py-32 text-slate-500 border border-dashed border-slate-800 rounded-xl bg-slate-900/20">
              <Server className="w-16 h-16 mb-4 opacity-30" />
              <p>يرجى تحديد مورد من القائمة لعرض جدول حجوزاته.</p>
            </div>
          ) : loadingBookings ? (
            <div className="flex justify-center py-20 text-slate-400">
              جاري تحميل الحجوزات...
            </div>
          ) : bookings.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 text-slate-400 bg-slate-900/30 rounded-xl border border-slate-800">
              <Calendar className="w-12 h-12 text-slate-600 mb-4 opacity-50" />
              <p>لا توجد حجوزات قادمة لهذا المورد.</p>
            </div>
          ) : (
            <div className="grid gap-3">
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              {bookings.map((booking: any) => (
                <div
                  key={booking.id}
                  className="bg-slate-950 border border-slate-800 p-4 rounded-xl flex justify-between items-center hover:border-indigo-500/30 transition-colors"
                >
                  <div className="flex items-center gap-4">
                    <div className="w-2 h-12 bg-indigo-500 rounded-full"></div>
                    <div>
                      <div className="font-bold text-slate-200">
                        {booking.title || `Booking #${booking.id}`}
                      </div>
                      <div className="text-xs text-slate-400 mt-1 flex items-center gap-2">
                        <Clock className="w-3 h-3" />
                        {new Date(booking.scheduledStart).toLocaleString("ar-LY")} -{" "}
                        {new Date(booking.scheduledEnd).toLocaleTimeString("ar-LY")}
                      </div>
                    </div>
                  </div>
                  <div>
                    <span className="text-xs font-bold px-3 py-1 bg-emerald-900/30 text-emerald-400 rounded-full border border-emerald-500/20">
                      {booking.status}
                    </span>
                    <button
                      onClick={() => {
                        if (confirm("هل تريد إلغاء هذا الحجز؟")) {
                          cancelMutation.mutate(booking.id);
                        }
                      }}
                      className="mr-3 text-rose-500 hover:text-rose-400 p-1"
                      title="إلغاء الحجز"
                    >
                      <XCircle className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {showBookingModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/80 backdrop-blur-sm p-4">
          <div className="bg-slate-900 border border-indigo-500/50 rounded-2xl w-full max-w-md overflow-hidden shadow-[0_0_40px_-10px_rgba(99,102,241,0.3)]">
            <div className="p-4 border-b border-slate-800 flex justify-between items-center bg-slate-900/50">
              <h3 className="text-lg font-bold text-indigo-400">حجز مورد جديد</h3>
              <button
                onClick={() => setShowBookingModal(false)}
                className="text-slate-400 hover:text-white"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="p-6 space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-400 mb-1">
                  رقم المريض
                </label>
                <input
                  type="number"
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm focus:border-indigo-500 outline-none"
                  value={patientId}
                  onChange={(e) => setPatientId(e.target.value)}
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-400 mb-1">
                  وقت البداية
                </label>
                <input
                  type="datetime-local"
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm focus:border-indigo-500 outline-none"
                  value={startTime}
                  onChange={(e) => setStartTime(e.target.value)}
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-400 mb-1">
                  وقت النهاية
                </label>
                <input
                  type="datetime-local"
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm focus:border-indigo-500 outline-none"
                  value={endTime}
                  onChange={(e) => setEndTime(e.target.value)}
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-400 mb-1">
                  ملاحظات
                </label>
                <textarea
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm focus:border-indigo-500 outline-none"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                ></textarea>
              </div>
            </div>
            <div className="p-4 border-t border-slate-800 bg-slate-900/50 flex justify-end gap-3">
              <button
                onClick={() => setShowBookingModal(false)}
                className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-sm transition-colors"
              >
                إلغاء
              </button>
              <button
                onClick={() => bookMutation.mutate()}
                disabled={!patientId || !startTime || !endTime || bookMutation.isPending}
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-lg text-sm shadow-lg transition-colors disabled:opacity-50"
              >
                تأكيد الحجز
              </button>
            </div>
          </div>
        </div>
      )}

      {showCreateResourceModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/80 backdrop-blur-sm p-4">
          <div className="bg-slate-900 border border-emerald-500/50 rounded-2xl w-full max-w-md overflow-hidden shadow-[0_0_40px_-10px_rgba(16,185,129,0.25)]">
            <div className="p-4 border-b border-slate-800 flex justify-between items-center bg-slate-900/50">
              <h3 className="text-lg font-bold text-emerald-400">إضافة مورد جديد</h3>
              <button
                onClick={() => setShowCreateResourceModal(false)}
                className="text-slate-400 hover:text-white"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="p-6 space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-400 mb-1">
                  اسم المورد
                </label>
                <input
                  type="text"
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm focus:border-emerald-500 outline-none"
                  value={resourceName}
                  onChange={(e) => setResourceName(e.target.value)}
                  placeholder="مثال: MRI Room 1"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-400 mb-1">
                  نوع المورد
                </label>
                <select
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm focus:border-emerald-500 outline-none"
                  value={resourceType}
                  onChange={(e) => setResourceType(e.target.value)}
                >
                  <option value="ROOM">ROOM</option>
                  <option value="EQUIPMENT">EQUIPMENT</option>
                  <option value="THEATER">THEATER</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-400 mb-1">
                  القسم
                </label>
                <select
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm focus:border-emerald-500 outline-none"
                  value={resourceDepartmentId}
                  onChange={(e) => setResourceDepartmentId(e.target.value)}
                >
                  <option value="">-- بدون قسم --</option>
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                  {departments.map((dept: any) => (
                    <option key={dept.id} value={dept.id}>
                      {dept.name}
                    </option>
                  ))}
                </select>
              </div>
            </div>
            <div className="p-4 border-t border-slate-800 bg-slate-900/50 flex justify-end gap-3">
              <button
                onClick={() => setShowCreateResourceModal(false)}
                className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-sm transition-colors"
              >
                إلغاء
              </button>
              <button
                onClick={() => createResourceMutation.mutate()}
                disabled={!resourceName.trim() || createResourceMutation.isPending}
                className="px-4 py-2 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded-lg text-sm shadow-lg transition-colors disabled:opacity-50"
              >
                حفظ المورد
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useMemo, useState } from "react";
import { useMutation, useQuery } from "@tanstack/react-query";
import { Link } from "react-router-dom";
import {
  ArrowUpCircle,
  Clock,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  Search,
  Server,
  UserPlus,
} from "lucide-react";
import { toast } from "sonner";
import { clinicalServices } from "../../../api/clinicalServices";
import { apiClient } from "../../../api/apiClient";
import { useAuthStore } from "../../../stores/authStore";

const PRIORITY_MAP: Record<string, number> = {
  URGENT: 1,
  HIGH: 2,
  NORMAL: 3,
};

export default function WaitlistManager() {
  const { user } = useAuthStore();
  const hospitalId = user?.hospitalId || 1;

  const [showAddModal, setShowAddModal] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [foundPatient, setFoundPatient] = useState<any>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [resourceId, setResourceId] = useState("");
  const [priority, setPriority] = useState("NORMAL");
  const [notes, setNotes] = useState("");

  const { data: waitlist = [], isLoading, refetch } = useQuery({
    queryKey: ["waitlist", hospitalId],
    queryFn: () => clinicalServices.getWaitlist(hospitalId),
  });

  const { data: resources = [] } = useQuery({
    queryKey: ["resources", hospitalId],
    queryFn: () => clinicalServices.getResources(hospitalId),
  });

  const selectedResource = useMemo(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    () => resources.find((resource: any) => resource.id === Number(resourceId)),
    [resourceId, resources],
  );

  const addMutation = useMutation({
    mutationFn: async () => {
      const noteParts = [
        selectedResource ? `المورد المطلوب: ${selectedResource.name}` : null,
        notes.trim() || null,
      ].filter(Boolean);

      await clinicalServices.joinWaitlist({
        hospitalId,
        patientId: foundPatient.id,
        resourceId: selectedResource?.id || undefined,
        departmentId: selectedResource?.departmentId || undefined,
        priority: PRIORITY_MAP[priority] ?? 3,
        notes: noteParts.join("\n"),
      });
    },
    onSuccess: () => {
      toast.success("تمت إضافة المريض لقائمة الانتظار.");
      setShowAddModal(false);
      setFoundPatient(null);
      setSearchQuery("");
      setResourceId("");
      setPriority("NORMAL");
      setNotes("");
      refetch();
    },
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    onError: (err: any) =>
      toast.error(err.response?.data?.message || "فشل إضافة المريض لقائمة الانتظار."),
  });

  const searchPatient = async () => {
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    try {
      const res = await apiClient.get(
        `/patients/search?query=${encodeURIComponent(searchQuery)}`,
      );
      if (res.data.length > 0) {
        setFoundPatient(res.data[0]);
        toast.success("تم العثور على المريض");
      } else {
        toast.error("لم يتم العثور على المريض");
        setFoundPatient(null);
      }
    } catch {
      toast.error("خطأ في البحث");
      setFoundPatient(null);
    } finally {
      setIsSearching(false);
    }
  };

  const statusLabel = (status: string) => {
    if (status === "NOTIFIED") return "تم الإشعار";
    if (status === "BOOKED") return "تم الحجز";
    if (status === "CANCELLED") return "ملغى";
    return "قيد الانتظار";
  };

  const priorityLabel = (value: number) => {
    if (value === 1) return "عاجل";
    if (value === 2) return "عالي";
    return "عادي";
  };

  return (
    <div className="flex flex-col h-full text-slate-100 p-4 md:p-6 space-y-6 overflow-hidden">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 shadow-sm relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-amber-500/10 rounded-full blur-3xl pointer-events-none" />
        <div className="relative z-10">
          <h1 className="text-2xl font-bold text-white flex items-center gap-3">
            <div className="p-2 bg-amber-500/20 text-amber-400 rounded-xl">
              <Clock className="w-6 h-6" />
            </div>
            قوائم الانتظار الذكية
          </h1>
          <p className="text-sm text-slate-400 mt-1">
            متابعة المرضى بانتظار الموارد السريرية مع ترتيب حسب الأولوية والقسم.
          </p>
        </div>
        <div className="relative z-10 flex gap-2">
          <Link
            to="/clinical/scheduling"
            className="bg-indigo-600/20 text-indigo-400 border border-indigo-500/30 hover:bg-indigo-600/40 px-4 py-2 rounded-xl text-sm font-bold transition-colors flex items-center gap-2 shadow-lg"
          >
            <Server className="w-4 h-4" /> جدولة الموارد
          </Link>
          <button
            onClick={() => setShowAddModal(true)}
            className="bg-amber-600 hover:bg-amber-500 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-lg transition-colors flex items-center gap-2"
          >
            <UserPlus className="w-4 h-4" /> إضافة مريض
          </button>
        </div>
      </div>

      <div className="flex-1 bg-slate-900/40 border border-slate-800 rounded-2xl p-5 overflow-y-auto custom-scrollbar relative">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 text-slate-400">
            <div className="w-12 h-12 rounded-full border-4 border-amber-500/30 border-t-amber-500 animate-spin mb-4"></div>
            <p className="animate-pulse">جاري تحميل قائمة الانتظار...</p>
          </div>
        ) : waitlist.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-slate-400 bg-slate-900/50 rounded-xl border border-dashed border-slate-700">
            <Clock className="w-16 h-16 text-slate-600 mb-4 opacity-50" />
            <p>قائمة الانتظار فارغة حاليًا.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            {waitlist.map((entry: any) => (
              <div
                key={entry.id}
                className={`bg-slate-900 border ${
                  entry.status === "NOTIFIED"
                    ? "border-emerald-500/50 shadow-[0_0_15px_-3px_rgba(16,185,129,0.3)]"
                    : "border-slate-800"
                } rounded-2xl p-5 relative overflow-hidden`}
              >
                {entry.status === "NOTIFIED" && (
                  <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 rounded-full blur-2xl -mx-10 -my-10 pointer-events-none" />
                )}

                <div className="flex justify-between items-start mb-4 relative z-10">
                  <div>
                    <h3 className="font-bold text-slate-200 text-lg">
                      {entry.patient?.fullName || `المريض #${entry.patientId}`}
                    </h3>
                    <div className="text-xs text-slate-500 flex items-center gap-1 mt-1">
                      <Server className="w-3 h-3" />
                      {entry.resource?.name || entry.department?.name || "بدون قسم محدد"}
                    </div>
                  </div>
                  <div className="text-right">
                    <span
                      className={`px-2 py-1 rounded text-[10px] font-bold ${
                        entry.priority === 1
                          ? "bg-rose-600 text-white animate-pulse"
                          : entry.priority === 2
                            ? "bg-rose-900/30 text-rose-400 border border-rose-500/20"
                            : "bg-slate-800 text-slate-400"
                      }`}
                    >
                      {priorityLabel(entry.priority)}
                    </span>
                  </div>
                </div>

                {entry.notes && (
                  <div className="text-xs text-slate-400 bg-slate-950/70 border border-slate-800 rounded-xl p-3 mb-4 whitespace-pre-line">
                    {entry.notes}
                  </div>
                )}

                <div className="mt-4 relative z-10 flex justify-between items-center">
                  <div>
                    <span
                      className={`text-xs font-bold ${
                        entry.status === "WAITING"
                          ? "text-amber-400"
                          : entry.status === "NOTIFIED"
                            ? "text-emerald-400 flex items-center gap-1"
                            : "text-slate-500"
                      }`}
                    >
                      {entry.status === "NOTIFIED" && (
                        <ArrowUpCircle className="w-4 h-4" />
                      )}
                      {statusLabel(entry.status)}
                    </span>
                  </div>
                  <div className="text-[10px] text-slate-500">
                    أضيف:{" "}
                    {new Date(entry.requestedDate || entry.createdAt).toLocaleDateString(
                      "ar-LY",
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/80 backdrop-blur-sm p-4">
          <div className="bg-slate-900 border border-amber-500/50 rounded-2xl w-full max-w-md overflow-hidden shadow-[0_0_40px_-10px_rgba(245,158,11,0.2)]">
            <div className="p-4 border-b border-slate-800 flex justify-between items-center bg-slate-900/50">
              <h3 className="text-lg font-bold text-amber-400">إضافة مريض لقائمة الانتظار</h3>
            </div>
            <div className="p-6 space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-400 mb-1">
                  البحث عن مريض
                </label>
                <div className="flex gap-2">
                  <input
                    type="text"
                    className="flex-1 bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm focus:border-amber-500 outline-none"
                    placeholder="الاسم، رقم الملف، أو الهاتف..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && searchPatient()}
                  />
                  <button
                    onClick={searchPatient}
                    disabled={isSearching}
                    className="bg-amber-600 hover:bg-amber-500 text-white px-4 py-2 rounded-xl text-sm font-bold transition-colors disabled:opacity-50"
                  >
                    {isSearching ? "بحث..." : "بحث"}
                  </button>
                </div>
                {foundPatient && (
                  <div className="mt-3 bg-amber-900/20 border border-amber-500/30 rounded-xl p-3 text-sm">
                    <div className="font-bold text-white">{foundPatient.fullName}</div>
                    <div className="text-xs text-amber-300 mt-1">
                      MRN: {foundPatient.mrn}
                    </div>
                  </div>
                )}
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-400 mb-1">
                  المورد المطلوب
                </label>
                <select
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm focus:border-amber-500 outline-none"
                  value={resourceId}
                  onChange={(e) => setResourceId(e.target.value)}
                >
                  <option value="">-- اختر المورد --</option>
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                  {resources.map((resource: any) => (
                    <option key={resource.id} value={resource.id}>
                      {resource.name} ({resource.type})
                    </option>
                  ))}
                </select>
                {selectedResource?.department?.name && (
                  <div className="text-[11px] text-slate-500 mt-2">
                    سيتم ربط الطلب بالقسم: {selectedResource.department.name}
                  </div>
                )}
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-400 mb-1">
                  الأولوية
                </label>
                <select
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm focus:border-amber-500 outline-none"
                  value={priority}
                  onChange={(e) => setPriority(e.target.value)}
                >
                  <option value="NORMAL">عادي</option>
                  <option value="HIGH">عالي</option>
                  <option value="URGENT">عاجل</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-400 mb-1">
                  ملاحظات
                </label>
                <textarea
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-sm focus:border-amber-500 outline-none"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                ></textarea>
              </div>
            </div>
            <div className="p-4 border-t border-slate-800 bg-slate-900/50 flex justify-end gap-3">
              <button
                onClick={() => setShowAddModal(false)}
                className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-sm transition-colors"
              >
                إلغاء
              </button>
              <button
                onClick={() => addMutation.mutate()}
                disabled={!foundPatient || !resourceId || addMutation.isPending}
                className="px-4 py-2 bg-amber-600 hover:bg-amber-500 text-white font-bold rounded-lg text-sm shadow-lg transition-colors disabled:opacity-50"
              >
                إضافة للقائمة
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

