              data={stats?.hourlyActivity || [
                { hour: "8ص", visits: 15, appointments: 8 },
                { hour: "9ص", visits: 25, appointments: 15 },
                { hour: "10ص", visits: 35, appointments: 22 },
                { hour: "11ص", visits: 30, appointments: 18 },
