      {/* Recent Activities */}
      <div className={cardClass}>
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-slate-300 font-bold">الأنشطة الحديثة</h3>
          <div className="flex items-center gap-2 text-xs text-slate-400">
            <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
            مباشر
          </div>
        </div>
        <div className="space-y-2 max-h-64 overflow-y-auto">
          {activitiesLoading ? (
            <div className="text-center text-slate-500 py-8">جاري تحميل الأنشطة...</div>
          ) : activities.length === 0 ? (
            <div className="text-center text-slate-500 py-8">لا توجد أنشطة حديثة</div>
          ) : (
            activities.slice(0, 10).map((activity) => (
              <div
                key={activity.id}
                className={`flex items-center gap-3 p-3 rounded-lg border ${getPriorityColor(activity.priority)}`}
              >
                <div className="text-slate-300">
                  {getActivityIcon(activity.type)}
                </div>
                <div className="flex-1">
                  <div className="flex justify-between items-start">
                    <div>
                      <div className="text-sm font-medium text-white">
                        {activity.patientName}
                      </div>
                      <div className="text-xs text-slate-400">
                        {activity.description}
                      </div>
                    </div>
                    <div className="text-xs text-slate-500">
                      {new Date(activity.timestamp).toLocaleTimeString("ar-LY", {
                        hour: '2-digit',
                        minute: '2-digit'
                      })}
                    </div>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { toast } from "sonner";
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { inventoryApi, MaterialRequestItem } from "@/api/inventoryApi";
import { apiClient } from "@/api/apiClient";

export function CreateMaterialRequestPage() {
  const navigate = useNavigate();
  const [requestingWarehouseId, setRequestingWarehouseId] = useState<string>("");
  const [fulfillingWarehouseId, setFulfillingWarehouseId] = useState<string>("");
  const [notes, setNotes] = useState("");
  const [items, setItems] = useState<{ productId: string; requestedQty: number; uomId?: string }[]>([]);
  const [saving, setSaving] = useState(false);

  // Load Warehouses
  const { data: warehouses = [] } = useQuery({
    queryKey: ['warehouses'],
    queryFn: async () => {
      const res = await inventoryApi.getWarehouses();
      return res;
    }
  });

  // Load Products (Simplistic implementation for demo - usually a paginated search or select)
  const { data: products = [] } = useQuery({
    queryKey: ['products'],
    queryFn: async () => {
      const res = await apiClient.get('/inventory/products');
      return res.data;
    }
  });

  const addItem = () => {
    setItems([...items, { productId: "", requestedQty: 1 }]);
  };

  const removeItem = (index: number) => {
    const newItems = [...items];
    newItems.splice(index, 1);
    setItems(newItems);
  };

  const handleItemChange = (index: number, field: string, value: string | number) => {
    const newItems = [...items];
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (newItems[index] as any)[field] = value;
    setItems(newItems);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!requestingWarehouseId || !fulfillingWarehouseId) {
      toast.error("يرجى اختيار المستودع الطالب والمستودع المصرف");
      return;
    }

    if (requestingWarehouseId === fulfillingWarehouseId) {
      toast.error("لا يمكن أن يكون المستودع الطالب هو نفسه المستودع المصرف");
      return;
    }

    if (items.length === 0) {
      toast.error("يرجى إضافة صنف واحد على الأقل");
      return;
    }

    const invalidItems = items.some(i => !i.productId || i.requestedQty <= 0);
    if (invalidItems) {
      toast.error("يرجى التأكد من اختيار الصنف وتحديد كمية صحيحة لكل سطر");
      return;
    }

    setSaving(true);
    try {
      const payload = {
        requestingWarehouseId: Number(requestingWarehouseId),
        fulfillingWarehouseId: Number(fulfillingWarehouseId),
        notes: notes || undefined,
        items: items.map(i => ({
          productId: Number(i.productId),
          requestedQty: Number(i.requestedQty),
          uomId: i.uomId ? Number(i.uomId) : undefined
        }))
      };

      const res = await inventoryApi.createMaterialRequest(payload);
      toast.success("تم إنشاء طلب المواد بنجاح");
      navigate(`/inventory/material-requests/${res.id}`);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (error: any) {
      console.error(error);
      toast.error(error.response?.data?.message || "حدث خطأ أثناء إنشاء الطلب");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="flex flex-col h-full text-slate-100 p-4 md:p-6 space-y-6 overflow-y-auto custom-scrollbar" dir="rtl">
      {/* Header */}
      <div className="flex justify-between items-center bg-slate-900 border border-slate-800 rounded-2xl p-5 shadow-sm">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center gap-3">
            <div className="p-2 bg-amber-500/20 text-amber-400 rounded-xl">
               ➕
            </div>
            طلب مواد جديد
          </h1>
          <p className="text-sm text-slate-400 mt-1">
            إنشاء طلب جديد لسحب مواد من المستودع الرئيسي أو مستودع آخر.
          </p>
        </div>
        <div className="flex gap-3">
          <button
            onClick={() => navigate("/inventory/material-requests")}
            className="px-5 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl text-sm font-bold transition-colors"
          >
            إلغاء
          </button>
          <button
            onClick={handleSubmit}
            disabled={saving}
            className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-white rounded-xl text-sm font-bold shadow-lg shadow-amber-900/20 transition-all disabled:opacity-50"
          >
            {saving ? "جاري الحفظ..." : "حفظ الطلب"}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Form Details */}
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
            <h2 className="text-base font-bold text-slate-200 mb-6 border-b border-slate-800 pb-2">
              البيانات الأساسية
            </h2>

            <div className="space-y-4">
              <div className="flex flex-col gap-2">
                <label className="text-xs font-bold text-slate-400">المستودع الطالب (طالب المواد) <span className="text-rose-400">*</span></label>
                <select
                  value={requestingWarehouseId}
                  onChange={(e) => setRequestingWarehouseId(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl py-2.5 px-3 text-sm focus:border-amber-500 outline-none transition-all"
                >
                  <option value="">اختر المستودع...</option>
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                  {warehouses.map((w: any) => (
                    <option key={w.id} value={w.id}>{w.name}</option>
                  ))}
                </select>
              </div>

              <div className="flex flex-col gap-2">
                <label className="text-xs font-bold text-slate-400">المستودع المصرف (المصدر) <span className="text-rose-400">*</span></label>
                <select
                  value={fulfillingWarehouseId}
                  onChange={(e) => setFulfillingWarehouseId(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl py-2.5 px-3 text-sm focus:border-amber-500 outline-none transition-all"
                >
                  <option value="">اختر المستودع...</option>
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                  {warehouses.map((w: any) => (
                    <option key={w.id} value={w.id}>{w.name}</option>
                  ))}
                </select>
              </div>

              <div className="flex flex-col gap-2 pt-2">
                <label className="text-xs font-bold text-slate-400">ملاحظات الطلب</label>
                <textarea
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder="ملاحظات إضافية للمستودع المصرف..."
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl py-2.5 px-3 text-sm focus:border-amber-500 outline-none transition-all min-h-[100px] resize-none"
                />
              </div>
            </div>
          </div>
        </div>

        {/* Right Column: Items */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
            <div className="flex justify-between items-center border-b border-slate-800 pb-4 mb-4">
              <h2 className="text-base font-bold text-slate-200">
                الأصناف المطلوبة
              </h2>
              <button
                type="button"
                onClick={addItem}
                className="px-4 py-1.5 bg-slate-800 hover:bg-slate-700 text-amber-400 rounded-lg text-xs font-bold border border-slate-700 transition-all flex items-center gap-1"
              >
                <span>+</span> إضافة صنف
              </button>
            </div>

            {items.length === 0 ? (
              <div className="text-center py-12 text-slate-500 border border-dashed border-slate-800 rounded-xl bg-slate-950/50">
                <p className="text-sm">لم يتم إضافة أي أصناف للطلب</p>
                <button
                  type="button"
                  onClick={addItem}
                  className="mt-3 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-xs font-bold transition-all"
                >
                  إضافة الصنف الأول
                </button>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm text-right">
                  <thead className="text-[10px] uppercase text-slate-500 bg-slate-950/50">
                    <tr>
                      <th className="px-3 py-3 font-bold rounded-r-xl">الصنف</th>
                      <th className="px-3 py-3 font-bold w-32">الكمية</th>
                      <th className="px-3 py-3 font-bold w-40">الوحدة (UOM)</th>
                      <th className="px-3 py-3 font-bold w-16 text-center rounded-l-xl"></th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50">
                    {items.map((item, index) => (
                      <tr key={index}>
                        <td className="px-2 py-3">
                          <select
                            value={item.productId}
                            onChange={(e) => handleItemChange(index, "productId", e.target.value)}
                            className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-2 text-xs focus:border-amber-500 outline-none"
                          >
                            <option value="">اختر الصنف...</option>
                            // eslint-disable-next-line @typescript-eslint/no-explicit-any
                            {products.map((p: any) => (
                              <option key={p.id} value={p.id}>{p.code ? `[${p.code}] ` : ''}{p.name}</option>
                            ))}
                          </select>
                        </td>
                        <td className="px-2 py-3">
                          <input
                            type="number"
                            min="1"
                            value={item.requestedQty}
                            onChange={(e) => handleItemChange(index, "requestedQty", e.target.value)}
                            className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-2 text-xs focus:border-amber-500 outline-none text-center"
                          />
                        </td>
                        <td className="px-2 py-3">
                           {/* Simplified for demo: ideally would load product-specific UOMs */}
                          <select
                            value={item.uomId || ""}
                            onChange={(e) => handleItemChange(index, "uomId", e.target.value)}
                            className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-2 text-xs focus:border-amber-500 outline-none"
                          >
                            <option value="">الوحدة الأساسية</option>
                            {/* Will be populated dynamically based on selected product in a real scenario */}
                          </select>
                        </td>
                        <td className="px-2 py-3 text-center">
                          <button
                            type="button"
                            onClick={() => removeItem(index)}
                            className="p-1.5 text-rose-500 hover:bg-rose-500/10 rounded-lg transition-colors"
                            title="حذف السطر"
                          >
                            ❌
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import { apiClient } from "@/api/apiClient";
import { InventoryAlertsWidget } from "../../components/inventory/InventoryAlertsWidget";
import { formatMoney } from "@/lib/utils"; // Assuming utils has formatMoney
import { 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  BarChart,
  Bar,
  Legend
} from 'recharts';
import { Package, AlertCircle, RefreshCcw, TrendingUp, Loader2 } from "lucide-react";

import { useAuth } from "@/hooks/useAuth";
import { useQuery } from "@tanstack/react-query";

const COLORS = ['#10b981', '#0ea5e9', '#f59e0b', '#ef4444'];

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const StatCard = ({ title, value, icon: Icon, colorClass }: any) => (
    <div className="bg-slate-900/50 border border-slate-800 p-6 rounded-2xl flex items-center gap-4 shadow-lg hover:bg-slate-800/50 transition-colors">
        <div className={`p-4 rounded-xl ${colorClass} bg-opacity-20`}>
            <Icon className={`w-6 h-6 ${colorClass.replace('bg-', 'text-')}`} />
        </div>
        <div>
            <div className="text-slate-400 text-sm font-medium">{title}</div>
            <div className="text-2xl font-black text-white mt-1">{value}</div>
        </div>
    </div>
);

export function InventoryDashboardPage() {
  const { user } = useAuth();
  const [selectedWarehouseId, setSelectedWarehouseId] = useState<string>("all");

  // 1. Fetch Warehouses
  const { data: warehouses = [] } = useQuery({
    queryKey: ['warehouses', user?.hospitalId],
    queryFn: async () => {
       const res = await apiClient.get('/inventory/warehouses');
       return res.data;
    },
    enabled: !!user?.hospitalId
  });

  // 2. Fetch Stats
  const { data: stats, isLoading: statsLoading, isError } = useQuery({
    queryKey: ['inventoryStats', user?.hospitalId, selectedWarehouseId],
    queryFn: async () => {
        let url = `/inventory/counts/dashboard/stats?hospitalId=${user?.hospitalId}`;
        if (selectedWarehouseId !== "all") {
            url += `&warehouseId=${selectedWarehouseId}`;
        }
        const res = await apiClient.get(url);
        return res.data;
    },
    enabled: !!user?.hospitalId,
    staleTime: 60 * 1000, // Client side cache for 1 min
  });

  if (statsLoading) {
      return <div className="flex h-full items-center justify-center text-slate-500"><Loader2 className="animate-spin w-8 h-8" /></div>;
  }
  
  if (isError) return <div className="p-8 text-center text-rose-500">فشل تحميل البيانات</div>;
  if (!stats) return null; // Or skeleton

  return (
    <div className="flex flex-col h-full text-slate-100 p-4 md:p-6 space-y-6 overflow-y-auto custom-scrollbar" dir="rtl">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
           <h1 className="text-3xl font-black text-white tracking-tight">لوحة تحكم المخزون</h1>
           <p className="text-sm text-slate-400">مراقبة التنبيهات، حركة الأصناف، وحالة المستودعات.</p>
        </div>

        {/* Warehouse Filter */}
        <div className="min-w-[200px]">
            <select 
                className="w-full bg-slate-900 border border-slate-700 text-slate-300 text-sm rounded-lg focus:ring-emerald-500 focus:border-emerald-500 block p-2.5"
                value={selectedWarehouseId}
                onChange={(e) => setSelectedWarehouseId(e.target.value)}
            >
                <option value="all">كل المستودعات</option>
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                {warehouses.map((w: any) => (
                    <option key={w.id} value={w.id}>{w.name}</option>
                ))}
            </select>
        </div>
      </div>

       {/* Stats Grid */}
       <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <StatCard title="إجمالي قيمة المخزون" value={`${formatMoney(stats.totalValue)} د.ل`} icon={TrendingUp} colorClass="bg-emerald-500" />
            <StatCard title="أصناف منخفضة الرصيد" value={`${stats.lowStockCount} صنف`} icon={AlertCircle} colorClass="bg-rose-500" />
            <StatCard title="أوامر شراء معلقة" value={`${stats.pendingOrders} طلبات`} icon={Package} colorClass="bg-amber-500" />
            <StatCard title="عمليات جرد نشطة" value={`${stats.activeCounts} عمليات`} icon={RefreshCcw} colorClass="bg-sky-500" />
       </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Charts Area */}
        <div className="lg:col-span-2 space-y-6">
            {/* Stock Value Trend */}
            <div className="bg-slate-900/50 border border-slate-800 rounded-3xl p-6 shadow-xl">
                 <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                    <TrendingUp className="w-5 h-5 text-emerald-500" />
                    تطور قيمة المخزون (تقريبي)
                 </h3>
                 <div className="h-[300px] w-full" dir="ltr">
                    <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={stats.stockTrend}>
                            <defs>
                                <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.3}/>
                                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                                </linearGradient>
                            </defs>
                            <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                            <XAxis dataKey="name" stroke="#64748b" tick={{fill: '#94a3b8'}} reversed />
                            <YAxis stroke="#64748b" tick={{fill: '#94a3b8'}} orientation="right" />
                            <Tooltip 
                                contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', borderRadius: '8px', color: '#f8fafc' }}
                                itemStyle={{ color: '#f8fafc' }}
                                labelStyle={{ color: '#94a3b8', marginBottom: '0.5rem' }}
                                formatter={(val: number) => [formatMoney(val), "القيمة"]}
                            />
                            <Area type="monotone" dataKey="value" stroke="#10b981" fillOpacity={1} fill="url(#colorValue)" />
                        </AreaChart>
                    </ResponsiveContainer>
                 </div>
            </div>

            {/* Low Stock Bar Chart */}
            <div className="bg-slate-900/50 border border-slate-800 rounded-3xl p-6 shadow-xl">
                 <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                    <AlertCircle className="w-5 h-5 text-rose-500" />
                    أصناف قاربت على النفاذ (Top 5)
                 </h3>
                 <div className="h-[250px] w-full" dir="ltr">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={stats.lowStockItems} layout="vertical">
                            <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" horizontal={false} />
                            <XAxis type="number" stroke="#64748b" orientation="top" />
                            <YAxis dataKey="name" type="category" width={100} stroke="#64748b" tick={{fill: '#e2e8f0', fontSize: 12}} orientation="right" />
                            <Tooltip 
                                cursor={{fill: '#1e293b'}} 
                                contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', borderRadius: '8px', color: '#f8fafc' }}
                                itemStyle={{ color: '#f8fafc' }}
                                labelStyle={{ color: '#94a3b8' }}
                            />
                            <Bar dataKey="qty" fill="#f43f5e" radius={[0, 4, 4, 0]} barSize={20} name="الكمية الحالية" />
                            <Bar dataKey="limit" fill="#334155" radius={[0, 4, 4, 0]} barSize={20} name="حد الطلب" />
                            <Legend wrapperStyle={{ paddingTop: '20px' }} />
                        </BarChart>
                    </ResponsiveContainer>
                 </div>
            </div>
        </div>

        {/* Sidebar: Alerts & Pie Chart */}
        <div className="lg:col-span-1 space-y-6">
          <InventoryAlertsWidget />

          <div className="bg-slate-900/50 border border-slate-800 rounded-3xl p-6 shadow-xl">
              <h3 className="text-lg font-bold text-white mb-6">حالة عمليات الجرد</h3>
              <div className="h-[200px] w-full" dir="ltr">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie
                            data={stats.statusDistribution}
                            cx="50%"
                            cy="50%"
                            innerRadius={60}
                            outerRadius={80}
                            paddingAngle={5}
                            dataKey="value"
