  const [malePatientId, setMalePatientId] = useState<number | ''>('');
  const [malePatientInfo, setMalePatientInfo] = useState<{ fullName: string; mrn: string } | null>(null);
  const [maleSearch, setMaleSearch] = useState('');
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [maleSearchResults, setMaleSearchResults] = useState<any[]>([]);
  const [showMaleResults, setShowMaleResults] = useState(false);
  const [infertilityType, setInfertilityType] = useState('UNEXPLAINED');
  const [diagnosis, setDiagnosis] = useState('');
  const [durationYears, setDurationYears] = useState<number | ''>('');
  const [amhLevel, setAmhLevel] = useState<number | ''>('');
  const [fshLevel, setFshLevel] = useState<number | ''>('');

  // Cycle Form
  const [cycleType, setCycleType] = useState('ICSI');
  const [protocol, setProtocol] = useState('');
  const [startDate, setStartDate] = useState('');

  useEffect(() => {
    if (caseId) loadCase(Number(caseId));
    else if (patientId) loadPatientCases(Number(patientId));
    else loadActiveCases();
  }, [caseId, patientId]);

  const loadCase = async (id: number) => {
    try { setLoading(true); const res = await apiClient.get(`/obgyn/fertility/cases/${id}`); setFertCase(res.data); } 
    catch { toast.error('فشل تحميل ملف العقم'); } 
    finally { setLoading(false); }
  };

  const loadPatientCases = async (pid: number) => {
    try { setLoading(true); const res = await apiClient.get(`/obgyn/fertility/cases/patient/${pid}`); setCases(res.data); } 
    catch { toast.error('فشل تحميل سجلات العقم'); } 
    finally { setLoading(false); }
  };

  const loadActiveCases = async () => {
    try { setLoading(true); const res = await apiClient.get('/obgyn/fertility/cases'); setCases(res.data); } 
    catch { toast.error('فشل تحميل الحالات'); } 
    finally { setLoading(false); }
  };

  const searchMalePatient = async (query: string) => {
    setMaleSearch(query);
    if (query.trim().length < 2) {
      setMaleSearchResults([]);
      setShowMaleResults(false);
      return;
    }
    try {
      const res = await apiClient.get('/patients', { params: { search: query.trim(), limit: 8 } });
      const items = res.data?.items || [];
      setMaleSearchResults(items);
      setShowMaleResults(items.length > 0);
    } catch { /* ignore */ }
  };

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const selectMalePatient = (p: any) => {
    setMalePatientId(p.id);
    setMalePatientInfo({ fullName: p.fullName, mrn: p.mrn });
    setMaleSearch('');
    setMaleSearchResults([]);
    setShowMaleResults(false);
  };

  const clearMalePatient = () => {
    setMalePatientId('');
    setMalePatientInfo(null);
    setMaleSearch('');
  };

  const handleCreateCase = async () => {
    if (!patientId) return toast.error('يرجى تحديد المريضة');
    try {
      const res = await apiClient.post('/obgyn/fertility/cases', {
        femalePatientId: Number(patientId),
        malePatientId: malePatientId || undefined,
        infertilityType, diagnosis, durationYears: durationYears || undefined,
        amhLevel: amhLevel || undefined, fshLevel: fshLevel || undefined,
      });
      toast.success('تم فتح ملف العقم بنجاح');
      setShowNewCaseForm(false);
      navigate(`/obgyn/fertility?caseId=${res.data.id}`);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) { toast.error(err.response?.data?.message || 'فشل إنشاء الملف'); }
  };

  const handleCreateCycle = async () => {
    if (!fertCase || !startDate) return toast.error('يرجى تحديد تاريخ البدء');
    try {
      await apiClient.post('/obgyn/fertility/cycles', {
        fertilityCaseId: fertCase.id, cycleType, protocol: protocol || undefined,
        startDate: new Date(startDate).toISOString(),
      });
      toast.success('تم بدء دورة علاجية جديدة');
      setShowNewCycleForm(false);
      loadCase(fertCase.id);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) { toast.error(err.response?.data?.message || 'فشل إنشاء الدورة'); }
  };

  const resultColors: Record<string, string> = {
    PENDING: 'text-slate-400 bg-slate-800 border-slate-600',
    POSITIVE: 'text-green-400 bg-green-900/30 border-green-500/40',
    NEGATIVE: 'text-red-400 bg-red-900/20 border-red-500/30',
    BIOCHEMICAL: 'text-amber-400 bg-amber-900/20 border-amber-500/30',
    ECTOPIC: 'text-red-400 bg-red-900/20 border-red-500/30',
    MISCARRIAGE: 'text-red-400 bg-red-900/20 border-red-500/30',
  };

  if (loading) return <div className="p-8 text-center text-slate-400">جاري التحميل...</div>;

  // === Case Detail View ===
  if (fertCase) {
    return (
      <div className="container mx-auto p-6 space-y-6" dir="rtl">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-white flex items-center gap-2">
              🧬 ملف العقم والحقن المجهري
            </h1>
            <p className="text-slate-400">
              👩 {fertCase.femalePatient?.fullName || '—'} (MRN: {fertCase.femalePatient?.mrn})
              {fertCase.malePatient && <> — 👨 {fertCase.malePatient.fullName} (MRN: {fertCase.malePatient.mrn})</>}
            </p>
          </div>
          <Button variant="secondary" onClick={() => navigate(-1)} className="bg-slate-800 text-slate-200 hover:bg-slate-700">رجوع</Button>
        </div>

        {/* Case Summary */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <Card className="bg-transparent border border-violet-500/30 text-center">
            <CardContent className="p-4">
              <div className="text-lg font-bold text-violet-400">{infertilityLabels[fertCase.infertilityType]}</div>
              <div className="text-xs text-slate-400 mt-1">نوع العقم</div>
            </CardContent>
          </Card>
          <Card className="bg-transparent border border-slate-700 text-center">
            <CardContent className="p-4">
              <div className="text-xl font-bold text-white">{fertCase.durationYears || '—'} سنة</div>
              <div className="text-xs text-slate-400 mt-1">مدة عدم الإنجاب</div>
            </CardContent>
          </Card>
          <Card className="bg-transparent border border-sky-500/30 text-center">
            <CardContent className="p-4">
              <div className="text-xl font-bold text-sky-400">{fertCase.cycles?.length || 0}</div>
              <div className="text-xs text-slate-400 mt-1">الدورات العلاجية</div>
            </CardContent>
          </Card>
          <Card className="bg-transparent border border-slate-700 text-center">
            <CardContent className="p-4">
              <div className={`text-lg font-bold ${fertCase.status === 'SUCCESSFUL' ? 'text-green-400' : 'text-white'}`}>
                {statusLabels[fertCase.status]}
              </div>
              <div className="text-xs text-slate-400 mt-1">الحالة</div>
            </CardContent>
          </Card>
        </div>

        {/* Couple Info & Lab Results */}
        <Card className="bg-transparent border border-slate-700 text-slate-100">
          <CardHeader><CardTitle className="text-white">البيانات التشخيصية</CardTitle></CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
              <div><span className="text-slate-400">الزوجة:</span> <span className="text-white font-bold">{fertCase.femalePatient?.fullName || '—'}</span></div>
              <div><span className="text-slate-400">الزوج:</span> <span className="text-white font-bold">{fertCase.malePatient?.fullName || 'غير مربوط'}</span></div>
              <div><span className="text-slate-400">AMH:</span> <span className="text-white font-bold">{fertCase.amhLevel || '—'} ng/mL</span></div>
              <div><span className="text-slate-400">FSH:</span> <span className="text-white font-bold">{fertCase.fshLevel || '—'} mIU/mL</span></div>
              <div className="col-span-2"><span className="text-slate-400">التشخيص:</span> <span className="text-white">{fertCase.diagnosis || '—'}</span></div>
              <div><span className="text-slate-400">تحاليل سائل منوي:</span> <span className="text-cyan-400 font-bold">{fertCase.semenAnalyses?.length || 0}</span></div>
              <div><span className="text-slate-400">زيارات ذكورة:</span> <span className="text-cyan-400 font-bold">{fertCase.andrologyVisits?.length || 0}</span></div>
            </div>
          </CardContent>
        </Card>

        {/* Cycles */}
        <Card className="bg-transparent border border-slate-700 text-slate-100">
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle className="text-white">الدورات العلاجية</CardTitle>
            {fertCase.status === 'ACTIVE' && (
              <Button onClick={() => setShowNewCycleForm(!showNewCycleForm)} className="bg-violet-600 hover:bg-violet-500 text-white">
                {showNewCycleForm ? 'إلغاء' : '+ دورة جديدة'}
              </Button>
            )}
          </CardHeader>
          <CardContent className="space-y-4">
            {showNewCycleForm && (
              <div className="bg-slate-900/60 p-4 rounded-lg border border-violet-500/30 space-y-3">
                <div className="grid grid-cols-3 gap-3">
                  <div className="space-y-1">
                    <Label className="text-slate-400">نوع الدورة</Label>
                    <Select value={cycleType} onValueChange={setCycleType}>
                      <SelectTrigger className="bg-slate-950 border-slate-700 text-white"><SelectValue /></SelectTrigger>
                      <SelectContent className="bg-slate-900 border-slate-700 text-white">
                        {Object.entries(cycleTypeLabels).map(([key, label]) => (
                          <SelectItem key={key} value={key} className="focus:bg-slate-800 focus:text-white">{label}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-1">
                    <Label className="text-slate-400">البروتوكول</Label>
                    <Select value={protocol || 'none'} onValueChange={v => setProtocol(v === 'none' ? '' : v)}>
                      <SelectTrigger className="bg-slate-950 border-slate-700 text-white"><SelectValue /></SelectTrigger>
                      <SelectContent className="bg-slate-900 border-slate-700 text-white">
                        <SelectItem value="none" className="focus:bg-slate-800 focus:text-white">—</SelectItem>
                        <SelectItem value="Long" className="focus:bg-slate-800 focus:text-white">Long Protocol</SelectItem>
                        <SelectItem value="Short" className="focus:bg-slate-800 focus:text-white">Short Protocol</SelectItem>
                        <SelectItem value="Antagonist" className="focus:bg-slate-800 focus:text-white">Antagonist</SelectItem>
                        <SelectItem value="Natural" className="focus:bg-slate-800 focus:text-white">Natural</SelectItem>
                        <SelectItem value="Mini-stim" className="focus:bg-slate-800 focus:text-white">Mini-stim</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-1">
                    <Label className="text-slate-400">تاريخ البدء</Label>
                    <Input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="bg-slate-950 border-slate-700 text-white" />
                  </div>
                </div>
                <Button onClick={handleCreateCycle} className="bg-violet-600 hover:bg-violet-500 text-white w-full">بدء الدورة</Button>
              </div>
            )}

            {fertCase.cycles && fertCase.cycles.length > 0 ? (
              <div className="space-y-3">
                {fertCase.cycles.map(cycle => (
                  <div 
                    key={cycle.id}
                    className={`p-4 rounded-lg border cursor-pointer transition-all ${
                      selectedCycle?.id === cycle.id ? 'border-violet-500 bg-violet-950/20' : 'border-slate-700 hover:border-violet-500/40'
                    }`}
                    onClick={() => setSelectedCycle(selectedCycle?.id === cycle.id ? null : cycle)}
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <span className="bg-violet-600 text-white text-xs px-2 py-1 rounded-full font-bold">#{cycle.cycleNumber}</span>
                        <span className="text-white font-bold">{cycleTypeLabels[cycle.cycleType] || cycle.cycleType}</span>
                        {cycle.protocol && <span className="text-slate-400 text-xs">({cycle.protocol})</span>}
                      </div>
                      <div className={`px-3 py-1 rounded-full text-xs font-bold border ${resultColors[cycle.pregnancyResult]}`}>
                        {resultLabels[cycle.pregnancyResult]}
                      </div>
                    </div>
                    
                    <div className="flex gap-4 mt-2 text-xs text-slate-400">
                      <span>بدأت: {new Date(cycle.startDate).toLocaleDateString('ar-LY')}</span>
                      {cycle.eggsRetrieved != null && <span>بويضات: <b className="text-sky-400">{cycle.eggsRetrieved}</b></span>}
                      {cycle.eggsFertilized != null && <span>مخصبة: <b className="text-green-400">{cycle.eggsFertilized}</b></span>}
                      {cycle.embryosTransferred != null && <span>مرجعة: <b className="text-pink-400">{cycle.embryosTransferred}</b></span>}
                      {cycle.embryosFrozen != null && <span>مجمدة: <b className="text-cyan-400">{cycle.embryosFrozen}</b> ❄️</span>}
                    </div>

                    {/* Expanded Cycle Details */}
                    {selectedCycle?.id === cycle.id && (
                      <div className="mt-4 space-y-3 border-t border-slate-700 pt-3">
                        <div className="grid grid-cols-3 md:grid-cols-6 gap-3 text-center">
                          {[
                            { label: 'أيام التحفيز', value: cycle.stimulationDays },
                            { label: 'بويضات ناضجة', value: cycle.eggsMature },
                            { label: 'أجنة يوم 3', value: cycle.embryosDay3 },
                            { label: 'أجنة يوم 5', value: cycle.embryosDay5 },
                            { label: 'سماكة البطانة', value: cycle.endometrialThickness ? `${cycle.endometrialThickness} مم` : null },
                            { label: 'Beta HCG', value: cycle.betaHCGResult },
                          ].map((item, idx) => (
                            <div key={idx} className="bg-slate-900/50 p-2 rounded-lg">
                              <div className="text-white font-bold">{item.value ?? '—'}</div>
                              <div className="text-[10px] text-slate-500">{item.label}</div>
                            </div>
                          ))}
                        </div>

                        {/* Embryos */}
                        {cycle.embryos && cycle.embryos.length > 0 && (
                          <div>
                            <h5 className="text-xs text-slate-400 font-bold mb-1">الأجنة:</h5>
                            <div className="flex gap-2 flex-wrap">
                              // eslint-disable-next-line @typescript-eslint/no-explicit-any
                              {cycle.embryos.map((e: any) => (
                                <span key={e.id} className={`px-2 py-1 rounded text-xs border ${
                                  e.status === 'FROZEN' ? 'border-cyan-500/40 bg-cyan-900/20 text-cyan-400' :
                                  e.status === 'TRANSFERRED' ? 'border-pink-500/40 bg-pink-900/20 text-pink-400' :
                                  'border-slate-600 bg-slate-800 text-slate-300'
                                }`}>
                                  #{e.embryoNumber} — D{e.day} {e.grade || ''} ({embryoStatusLabels[e.status] || e.status})
                                </span>
                              ))}
                            </div>
                          </div>
                        )}

                        {/* Medications */}
                        {cycle.medications && cycle.medications.length > 0 && (
                          <div>
                            <h5 className="text-xs text-slate-400 font-bold mb-1">الأدوية:</h5>
                            <div className="flex gap-2 flex-wrap">
                              // eslint-disable-next-line @typescript-eslint/no-explicit-any
                              {cycle.medications.map((m: any) => (
                                <span key={m.id} className="px-2 py-1 rounded text-xs border border-amber-500/30 bg-amber-900/10 text-amber-300">
                                  💊 {m.medicationName} — {m.dose} {m.route ? `(${m.route})` : ''}
                                </span>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-center text-slate-500 py-6">لا توجد دورات علاجية مسجلة بعد.</p>
            )}
          </CardContent>
        </Card>
      </div>
    );
  }

  // === Cases List View ===
  return (
    <div className="container mx-auto p-6 space-y-6" dir="rtl">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-white">🧬 الحقن المجهري وعلاج العقم</h1>
        <div className="flex gap-2">
          {patientId && (
            <Button onClick={() => setShowNewCaseForm(!showNewCaseForm)} className="bg-violet-600 hover:bg-violet-500 text-white">
              {showNewCaseForm ? 'إلغاء' : '+ فتح ملف جديد'}
            </Button>
          )}
          <Button variant="secondary" onClick={() => navigate(-1)} className="bg-slate-800 text-slate-200 hover:bg-slate-700">رجوع</Button>
        </div>
      </div>

      {showNewCaseForm && (
        <Card className="bg-transparent border border-violet-500/30 text-slate-100">
          <CardHeader><CardTitle className="text-violet-400">فتح ملف عقم جديد</CardTitle></CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="space-y-1 relative md:col-span-2">
                <Label className="text-slate-400">ملف الزوج (اختياري) — ابحث بالاسم أو رقم الملف</Label>
                {malePatientInfo ? (
                  <div className="flex items-center gap-2 bg-slate-900 border border-emerald-500/30 rounded-lg px-3 py-2">
                    <span className="text-emerald-400">👨</span>
                    <span className="text-white font-bold text-sm flex-1">{malePatientInfo.fullName}</span>
                    <span className="text-xs text-slate-400 font-mono">MRN: {malePatientInfo.mrn}</span>
                    <button type="button" onClick={clearMalePatient} className="text-red-400 hover:text-red-300 text-xs bg-slate-800 px-2 py-1 rounded">✕ إزالة</button>
                  </div>
                ) : (
                  <Input
                    value={maleSearch}
                    onChange={e => searchMalePatient(e.target.value)}
                    placeholder="ابحث عن الزوج بالاسم أو رقم الملف أو الهاتف..."
                    className="bg-slate-900 border-slate-700 text-white"
                    autoComplete="off"
                  />
                )}
                {showMaleResults && maleSearchResults.length > 0 && (
                  <div className="absolute top-full left-0 right-0 mt-1 bg-slate-900 border border-slate-600 rounded-xl shadow-2xl z-40 max-h-48 overflow-y-auto">
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    {maleSearchResults.map((p: any) => (
                      <button
                        key={p.id}
                        type="button"
                        onClick={() => selectMalePatient(p)}
                        className="w-full text-right px-3 py-2.5 hover:bg-violet-900/20 border-b border-slate-800/50 last:border-0 flex items-center gap-2 transition-colors text-sm"
                      >
                        <span className="text-lg">👨</span>
                        <div className="flex-1 min-w-0">
                          <div className="text-white font-bold truncate">{p.fullName}</div>
                          <div className="text-[10px] text-slate-400">MRN: <span className="text-violet-400 font-mono">{p.mrn}</span>{p.phone && <span className="mr-2">📞 {p.phone}</span>}</div>
                        </div>
                      </button>
                    ))}
                  </div>
                )}
              </div>
              <div className="space-y-1">
                <Label className="text-slate-400">نوع العقم</Label>
                <Select value={infertilityType} onValueChange={setInfertilityType}>
                  <SelectTrigger className="bg-slate-900 border-slate-700 text-white"><SelectValue /></SelectTrigger>
                  <SelectContent className="bg-slate-900 border-slate-700 text-white">
                    {Object.entries(infertilityLabels).map(([key, label]) => (
                      <SelectItem key={key} value={key} className="focus:bg-slate-800 focus:text-white">{label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1">
                <Label className="text-slate-400">مدة عدم الإنجاب (سنوات)</Label>
                <Input type="number" value={durationYears} onChange={e => setDurationYears(e.target.value ? Number(e.target.value) : '')} className="bg-slate-900 border-slate-700 text-white" />
              </div>
              <div className="space-y-1">
                <Label className="text-slate-400">AMH (ng/mL)</Label>
                <Input type="number" step="0.01" value={amhLevel} onChange={e => setAmhLevel(e.target.value ? Number(e.target.value) : '')} className="bg-slate-900 border-slate-700 text-white" />
              </div>
              <div className="space-y-1">
                <Label className="text-slate-400">FSH (mIU/mL)</Label>
                <Input type="number" step="0.01" value={fshLevel} onChange={e => setFshLevel(e.target.value ? Number(e.target.value) : '')} className="bg-slate-900 border-slate-700 text-white" />
              </div>
            </div>
            <div className="space-y-1">
              <Label className="text-slate-400">التشخيص</Label>
              <Input value={diagnosis} onChange={e => setDiagnosis(e.target.value)} placeholder="التشخيص التفصيلي..." className="bg-slate-900 border-slate-700 text-white" />
            </div>
            <Button onClick={handleCreateCase} className="bg-violet-600 hover:bg-violet-500 text-white w-full font-bold">فتح الملف</Button>
          </CardContent>
        </Card>
      )}

      {cases.length > 0 ? (
        <div className="space-y-3">
          {cases.map(c => (
            <Card key={c.id} className={`bg-transparent border cursor-pointer hover:border-violet-500/50 transition-colors ${c.status === 'ACTIVE' ? 'border-violet-500/30' : 'border-slate-700'}`} onClick={() => navigate(`/obgyn/fertility?caseId=${c.id}`)}>
              <CardContent className="p-4 flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <span className="text-2xl">🧬</span>
                  <div>
                    <div className="text-white font-bold">👩 {c.femalePatient?.fullName || `ملف #${c.id}`} {c.malePatient && <span className="text-slate-400 font-normal">+ 👨 {c.malePatient.fullName}</span>}</div>
                    <div className="text-xs text-slate-400">
                      {infertilityLabels[c.infertilityType]} — {c.durationYears ? `${c.durationYears} سنة` : ''}
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-xs text-slate-400">{c._count?.cycles || 0} دورات</span>
                  <span className={`px-3 py-1 rounded-full text-xs font-bold border ${c.status === 'ACTIVE' ? 'text-violet-400 bg-violet-900/20 border-violet-500/30' : 'text-slate-500 bg-slate-800 border-slate-700'}`}>
                    {statusLabels[c.status]}
                  </span>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : !showNewCaseForm ? (
        <div className="text-center py-12 text-slate-500">
          <p className="text-lg mb-2">{patientId ? 'لا توجد ملفات عقم لهذه المريضة.' : 'لا توجد حالات نشطة.'}</p>
          {patientId && <Button onClick={() => setShowNewCaseForm(true)} className="bg-violet-600 hover:bg-violet-500 text-white">فتح ملف عقم جديد</Button>}
        </div>
      ) : null}
    </div>
  );
}

/**
 * Patient Portal — Appointments Page & Booking Wizard
 * 
 * View upcoming & past appointments + Book new ones via a step-by-step wizard.
 */

import { useEffect, useState } from 'react';
import { portalApi } from '../../api/portalApi';
import { toast } from 'sonner';
import { Calendar, Plus, X, Loader2, Clock, User, Building2, ChevronRight, ChevronLeft, CheckCircle2 } from 'lucide-react';

export default function PortalAppointments() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [appointments, setAppointments] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  // Wizard State
  const [showWizard, setShowWizard] = useState(false);
  const [wizardStep, setWizardStep] = useState(1);
  const [wizardLoading, setWizardLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  // Directory Data
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [departments, setDepartments] = useState<any[]>([]);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [doctors, setDoctors] = useState<any[]>([]);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [availableSlots, setAvailableSlots] = useState<any[]>([]);

  // Selection State
  const [selectedDept, setSelectedDept] = useState<number | null>(null);
  const [selectedDoctor, setSelectedDoctor] = useState<number | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [selectedSlot, setSelectedSlot] = useState<string>('');
  const [bookingReason, setBookingReason] = useState('');

  const fetchAppointments = () => {
    setLoading(true);
    portalApi.get('/appointments')
      .then(res => setAppointments(res.data?.items || res.data || []))
      .catch(() => toast.error('فشل تحميل المواعيد'))
      .finally(() => setLoading(false));
  };

  useEffect(() => { fetchAppointments(); }, []);

  // Wizard Data Fetchers
  const fetchDepartments = async () => {
    setWizardLoading(true);
    try {
      const res = await portalApi.get('/directory/departments');
      setDepartments(res.data || []);
    } catch {
      toast.error('فشل تحميل الأقسام');
    } finally {
      setWizardLoading(false);
    }
  };

  const fetchDoctors = async (deptId: number) => {
    setWizardLoading(true);
    try {
      const res = await portalApi.get(`/directory/doctors?departmentId=${deptId}`);
      setDoctors(res.data || []);
    } catch {
      toast.error('فشل تحميل الأطباء');
    } finally {
      setWizardLoading(false);
    }
  };

  const fetchSlots = async (doctorId: number, date: string) => {
    setWizardLoading(true);
    try {
      const res = await portalApi.get(`/directory/doctors/${doctorId}/slots?date=${date}`);
      setAvailableSlots(res.data || []);
    } catch {
      toast.error('فشل تحميل المواعيد المتاحة');
    } finally {
      setWizardLoading(false);
    }
  };

  const startWizard = () => {
    setWizardStep(1);
    setSelectedDept(null);
    setSelectedDoctor(null);
    setSelectedDate('');
    setSelectedSlot('');
    setBookingReason('');
    setShowWizard(true);
    fetchDepartments();
  };

  const handleNextStep = () => {
    if (wizardStep === 1 && selectedDept) {
      fetchDoctors(selectedDept);
      setWizardStep(2);
    } else if (wizardStep === 2 && selectedDoctor) {
      setWizardStep(3);
    } else if (wizardStep === 3 && selectedSlot) {
      setWizardStep(4);
    }
  };

  const handleBook = async () => {
    setSubmitting(true);
    try {
      await portalApi.post('/appointments/book', {
        doctorId: selectedDoctor,
        scheduledStart: selectedSlot,
        reason: bookingReason || undefined,
      });
      toast.success('تم حجز الموعد بنجاح');
      setShowWizard(false);
      fetchAppointments();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'فشل حجز الموعد');
    } finally {
      setSubmitting(false);
    }
  };

  const handleCancel = async (id: number) => {
    if (!confirm('هل أنت متأكد من إلغاء هذا الموعد؟')) return;
    try {
      await portalApi.patch(`/appointments/${id}/cancel`);
      toast.success('تم إلغاء الموعد');
      fetchAppointments();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'فشل إلغاء الموعد');
    }
  };

  const statusLabels: Record<string, { label: string; className: string }> = {
    REQUESTED: { label: 'بانتظار التأكيد', className: 'status-pending' },
    CONFIRMED: { label: 'مؤكد', className: 'status-confirmed' },
    CHECKED_IN: { label: 'تم الحضور', className: 'status-active' },
    CALLED: { label: 'تم الاستدعاء', className: 'status-active' },
    COMPLETED: { label: 'مكتمل', className: 'status-completed' },
    CANCELLED: { label: 'ملغى', className: 'status-cancelled' },
    NO_SHOW: { label: 'لم يحضر', className: 'status-cancelled' },
  };

  return (
    <div className="portal-page">
      <div className="portal-page-header">
        <h1><Calendar size={28} /> المواعيد</h1>
        <button className="portal-primary-btn" onClick={startWizard}>
          <Plus size={18} /> حجز موعد جديد
        </button>
      </div>

      {/* Booking Wizard Modal */}
      {showWizard && (
        <div className="portal-modal-overlay">
          <div className="portal-modal" style={{ maxWidth: '600px' }}>
            <div className="portal-modal-header">
              <h2>معالج حجز موعد</h2>
              <button onClick={() => setShowWizard(false)}><X size={20} /></button>
            </div>

            <div className="wizard-progress">
              <div className={`wizard-step ${wizardStep >= 1 ? 'active' : ''}`}>القسم</div>
              <div className={`wizard-step ${wizardStep >= 2 ? 'active' : ''}`}>الطبيب</div>
              <div className={`wizard-step ${wizardStep >= 3 ? 'active' : ''}`}>الوقت</div>
              <div className={`wizard-step ${wizardStep >= 4 ? 'active' : ''}`}>التأكيد</div>
            </div>

            <div className="portal-form" style={{ minHeight: '300px' }}>
              {wizardLoading ? (
                <div className="portal-page-loader"><Loader2 className="animate-spin" size={30} /></div>
              ) : (
                <>
                  {/* STEP 1: Department */}
                  {wizardStep === 1 && (
                    <div className="wizard-grid">
                      {departments.map(dept => (
                        <div 
                          key={dept.id} 
                          className={`wizard-card ${selectedDept === dept.id ? 'selected' : ''}`}
                          onClick={() => setSelectedDept(dept.id)}
                        >
                          <Building2 size={24} />
                          <h3>{dept.name}</h3>
                        </div>
                      ))}
                      {departments.length === 0 && (
                        <div className="portal-empty small" style={{ gridColumn: '1 / -1', padding: '2rem' }}>
                          <Building2 size={36} className="text-muted" style={{ marginBottom: '1rem' }} />
                          <p style={{ fontWeight: 'bold' }}>لا توجد أقسام سريرية متاحة للحجز حالياً.</p>
                          <p className="text-muted" style={{ fontSize: '0.85rem', marginTop: '0.5rem' }}>يرجى التأكد من تهيئة النظام السريري أو التواصل مع الاستقبال.</p>
                        </div>
                      )}
                    </div>
                  )}

                  {/* STEP 2: Doctor */}
                  {wizardStep === 2 && (
                    <div className="wizard-grid">
                      {doctors.map(doc => (
                        <div 
                          key={doc.id} 
                          className={`wizard-card ${selectedDoctor === doc.id ? 'selected' : ''}`}
                          onClick={() => setSelectedDoctor(doc.id)}
                        >
                          <User size={24} />
                          <h3>د. {doc.fullName}</h3>
                          <p>{doc.specialty}</p>
                        </div>
                      ))}
                      {doctors.length === 0 && (
                        <div className="portal-empty small" style={{ gridColumn: '1 / -1', padding: '2rem' }}>
                          <User size={36} className="text-muted" style={{ marginBottom: '1rem' }} />
                          <p style={{ fontWeight: 'bold' }}>لا يوجد أطباء متاحين في هذا القسم حالياً.</p>
                        </div>
                      )}
                    </div>
                  )}

                  {/* STEP 3: Date & Slot */}
                  {wizardStep === 3 && (
                    <div className="wizard-date-slot">
                      <div className="portal-input-group">
                        <label>اختر التاريخ</label>
                        <input 
                          type="date" 
                          min={new Date().toISOString().split('T')[0]}
                          value={selectedDate}
                          onChange={(e) => {
                            setSelectedDate(e.target.value);
                            if (e.target.value) fetchSlots(selectedDoctor!, e.target.value);
                          }}
                        />
                      </div>

                      {selectedDate && (
                        <div className="slots-grid">
                          {availableSlots.length > 0 ? availableSlots.map(slot => (
                            <button
                              key={slot.time}
                              className={`slot-btn ${selectedSlot === slot.time ? 'selected' : ''}`}
                              onClick={() => setSelectedSlot(slot.time)}
                            >
                              <Clock size={16} />
                              {new Date(slot.time).toLocaleTimeString('ar-LY', { hour: '2-digit', minute: '2-digit' })}
                            </button>
                          )) : (
                            <div className="portal-empty small" style={{ gridColumn: '1 / -1', padding: '2rem' }}>
                              <Clock size={36} className="text-muted" style={{ marginBottom: '1rem' }} />
                              <p style={{ fontWeight: 'bold' }}>لا توجد فترات متاحة في هذا اليوم.</p>
                              <p className="text-muted" style={{ fontSize: '0.85rem', marginTop: '0.5rem' }}>يرجى اختيار يوم آخر.</p>
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  )}

                  {/* STEP 4: Confirm */}
                  {wizardStep === 4 && (
                    <div className="wizard-confirm">
                      <div className="confirm-summary">
                        <CheckCircle2 size={40} className="text-success mb-2" />
                        <h3>ملخص الحجز</h3>
                        <p><strong>الطبيب:</strong> {doctors.find(d => d.id === selectedDoctor)?.fullName}</p>
                        <p><strong>التاريخ والوقت:</strong> {new Date(selectedSlot).toLocaleString('ar-LY')}</p>
                      </div>
                      <div className="portal-input-group mt-4">
                        <label>سبب الزيارة (اختياري)</label>
                        <textarea 
                          value={bookingReason}
                          onChange={e => setBookingReason(e.target.value)}
                          placeholder="مثال: متابعة حالة السكري" 
                          rows={3}
                        />
                      </div>
                    </div>
                  )}
                </>
              )}
            </div>

            <div className="portal-modal-footer wizard-footer">
              {wizardStep > 1 ? (
                <button 
                  className="portal-secondary-btn" 
                  onClick={() => setWizardStep(wizardStep - 1)}
                  disabled={wizardLoading || submitting}
                >
                  <ChevronRight size={18} /> السابق
                </button>
              ) : <div></div>}

              {wizardStep < 4 ? (
                <button 
                  className="portal-primary-btn" 
                  onClick={handleNextStep}
                  disabled={
                    wizardLoading || 
                    (wizardStep === 1 && !selectedDept) ||
                    (wizardStep === 2 && !selectedDoctor) ||
                    (wizardStep === 3 && !selectedSlot)
                  }
                >
                  التالي <ChevronLeft size={18} />
                </button>
              ) : (
                <button 
                  className="portal-submit-btn" 
                  onClick={handleBook}
                  disabled={submitting || wizardLoading}
                >
                  {submitting ? <Loader2 className="animate-spin" size={18} /> : 'تأكيد الحجز النهائي'}
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Appointments List */}
      {loading ? (
        <div className="portal-page-loader"><Loader2 className="animate-spin" size={30} /></div>
      ) : appointments.length === 0 ? (
        <div className="portal-empty">
          <Calendar size={48} />
          <p>لا توجد مواعيد</p>
        </div>
      ) : (
        <div className="portal-list">
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          {appointments.map((apt: any) => {
            const status = statusLabels[apt.status] || { label: apt.status, className: '' };
            const canCancel = ['REQUESTED', 'CONFIRMED'].includes(apt.status);
            return (
              <div key={apt.id} className="portal-list-item">
                <div className="portal-list-item-content">
                  <div className="portal-list-item-top">
                    <span className={`portal-status ${status.className}`}>{status.label}</span>
                    <span className="portal-list-date">
                      <Clock size={14} />
                      {new Date(apt.scheduledStart).toLocaleDateString('ar-LY', {
                        weekday: 'short', month: 'short', day: 'numeric',
                        hour: '2-digit', minute: '2-digit',
                      })}
                    </span>
                  </div>
                  <div className="portal-list-item-details">
                    {apt.doctor && <span><User size={14} /> د. {apt.doctor.fullName}</span>}
                    {apt.department && <span><Building2 size={14} /> {apt.department.name}</span>}
                  </div>
                  {apt.reason && <p className="portal-list-item-note">{apt.reason}</p>}
                </div>
                {canCancel && (
                  <button className="portal-danger-btn" onClick={() => handleCancel(apt.id)}>
                    إلغاء
                  </button>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

/**
 * Patient Portal — Dashboard
 * 
 * Single-call summary view with cards for:
 * - Next appointment, Lab results, Balance, Messages, Refills
 * - Allergies + Insurance summary
 */

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { portalApi } from '../../api/portalApi';
import { usePortalAuthStore } from '../../stores/portalAuthStore';
import {
  Calendar, FlaskConical, CreditCard, MessageSquare,
  Pill, AlertTriangle, Shield, Activity, Loader2
} from 'lucide-react';

export default function PortalDashboard() {
  const navigate = useNavigate();
  const { patient } = usePortalAuthStore();
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [dashboard, setDashboard] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    portalApi.get('/medical/dashboard')
      .then(res => setDashboard(res.data))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div className="portal-page-loader">
        <Loader2 className="animate-spin" size={40} />
        <p>جارِ تحميل البيانات...</p>
      </div>
    );
  }

  const d = dashboard;

  return (
    <div className="portal-dashboard">
      {/* Welcome */}
      <div className="portal-welcome">
        <h1>مرحباً، {patient?.fullName} 👋</h1>
        <p>إليك ملخص حالتك الصحية</p>
      </div>

      {/* Summary Cards */}
      <div className="portal-cards-grid">
        {/* Next Appointment */}
        <div className="portal-card clickable" onClick={() => navigate('/portal/appointments')}>
          <div className="portal-card-icon" style={{ background: 'linear-gradient(135deg, #06b6d4, #0284c7)' }}>
            <Calendar size={24} />
          </div>
          <div className="portal-card-body">
            <h3>الموعد القادم</h3>
            {d?.nextAppointment ? (
              <>
                <p className="portal-card-value">
                  {new Date(d.nextAppointment.scheduledStart).toLocaleDateString('ar-LY', {
                    weekday: 'long', month: 'long', day: 'numeric',
                  })}
                </p>
                <p className="portal-card-sub">
                  د. {d.nextAppointment.doctor?.fullName}
                  {d.nextAppointment.department && ` — ${d.nextAppointment.department.name}`}
                </p>
              </>
            ) : (
              <p className="portal-card-empty">لا توجد مواعيد قادمة</p>
            )}
          </div>
        </div>

        {/* Lab Results */}
        <div className="portal-card clickable" onClick={() => navigate('/portal/records')}>
          <div className="portal-card-icon" style={{ background: 'linear-gradient(135deg, #8b5cf6, #7c3aed)' }}>
            <FlaskConical size={24} />
          </div>
          <div className="portal-card-body">
            <h3>آخر التحاليل</h3>
            {d?.recentLabResults?.length > 0 ? (
              <ul className="portal-card-list">
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                {d.recentLabResults.map((lab: any, i: number) => (
                  <li key={i}>{lab.test?.name}</li>
                ))}
              </ul>
            ) : (
              <p className="portal-card-empty">لا توجد نتائج حديثة</p>
            )}
          </div>
        </div>

        {/* Financial */}
        <div className="portal-card clickable" onClick={() => navigate('/portal/invoices')}>
          <div className="portal-card-icon" style={{ background: 'linear-gradient(135deg, #f59e0b, #d97706)' }}>
            <CreditCard size={24} />
          </div>
          <div className="portal-card-body">
            <h3>الرصيد المالي</h3>
            <p className="portal-card-value">
              {d?.financial?.outstandingBalance?.toFixed(3)} {d?.financial?.currency}
            </p>
            <p className="portal-card-sub">
              {d?.financial?.unpaidInvoices} فواتير غير مدفوعة
            </p>
          </div>
        </div>

        {/* Messages */}
        <div className="portal-card clickable" onClick={() => navigate('/portal/messages')}>
          <div className="portal-card-icon" style={{ background: 'linear-gradient(135deg, #10b981, #059669)' }}>
            <MessageSquare size={24} />
          </div>
          <div className="portal-card-body">
            <h3>المراسلات</h3>
            <p className="portal-card-value">
              {d?.messaging?.unreadCount || 0}
            </p>
            <p className="portal-card-sub">رسائل غير مقروءة</p>
          </div>
        </div>

        {/* Refills */}
        <div className="portal-card clickable" onClick={() => navigate('/portal/refills')}>
          <div className="portal-card-icon" style={{ background: 'linear-gradient(135deg, #ec4899, #db2777)' }}>
            <Pill size={24} />
          </div>
          <div className="portal-card-body">
            <h3>تجديد الوصفات</h3>
            <p className="portal-card-value">
              {d?.refills?.pendingCount || 0}
            </p>
            <p className="portal-card-sub">طلبات معلقة</p>
          </div>
        </div>

        {/* Active Medications */}
        <div className="portal-card">
          <div className="portal-card-icon" style={{ background: 'linear-gradient(135deg, #6366f1, #4f46e5)' }}>
            <Activity size={24} />
          </div>
          <div className="portal-card-body">
            <h3>الأدوية النشطة</h3>
            <p className="portal-card-value">{d?.activeMedications || 0}</p>
            <p className="portal-card-sub">وصفة نشطة</p>
          </div>
        </div>
      </div>

      {/* Bottom Row: Allergies + Insurance */}
      <div className="portal-info-row">
        {/* Allergies */}
        <div className="portal-info-card">
          <div className="portal-info-header">
            <AlertTriangle size={18} className="text-amber-400" />
            <h4>الحساسية</h4>
          </div>
          {d?.allergies?.length > 0 ? (
            <div className="portal-tags">
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              {d.allergies.map((a: any, i: number) => (
                <span key={i} className={`portal-tag ${a.severity === 'HIGH' ? 'danger' : a.severity === 'MODERATE' ? 'warning' : 'info'}`}>
                  {a.allergen}
                </span>
              ))}
            </div>
          ) : (
            <p className="portal-info-empty">لا توجد حساسية مسجلة</p>
          )}
        </div>

        {/* Insurance */}
        <div className="portal-info-card">
          <div className="portal-info-header">
            <Shield size={18} className="text-emerald-400" />
            <h4>التأمين</h4>
          </div>
          {d?.insurance ? (
            <div>
              <p className="portal-info-value">{d.insurance.provider}</p>
              <p className="portal-info-sub">{d.insurance.plan}</p>
            </div>
          ) : (
            <p className="portal-info-empty">لا يوجد تأمين مسجل</p>
          )}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { portalApi } from '../../api/portalApi';
import { CreditCard, Loader2, X } from 'lucide-react';
import { toast } from 'sonner';

export default function PortalInvoices() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [invoices, setInvoices] = useState<any[]>([]);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [balance, setBalance] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  // Payment Modal State
  const [showPayment, setShowPayment] = useState(false);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [selectedInvoice, setSelectedInvoice] = useState<any>(null);
  const [paymentAmount, setPaymentAmount] = useState<number | string>('');
  const [paymentMethod, setPaymentMethod] = useState('CREDIT_CARD');
  const [submittingPayment, setSubmittingPayment] = useState(false);

  const fetchFinancials = () => {
    setLoading(true);
    Promise.all([
      portalApi.get('/financial/invoices').then(r => setInvoices(r.data?.items || r.data || [])),
      portalApi.get('/financial/balance').then(r => setBalance(r.data)),
    ]).catch(() => {}).finally(() => setLoading(false));
  };

  useEffect(() => { fetchFinancials(); }, []);

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const openPaymentModal = (invoice: any) => {
    setSelectedInvoice(invoice);
    const remaining = Number(invoice.totalAmount) - Number(invoice.paidAmount);
    setPaymentAmount(remaining);
    setShowPayment(true);
  };

  const handlePay = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedInvoice || !paymentAmount) return;

    setSubmittingPayment(true);
    try {
      await portalApi.post(`/financial/pay/${selectedInvoice.id}`, {
        amount: Number(paymentAmount),
        paymentMethod,
      });
      toast.success('تمت عملية الدفع بنجاح');
      setShowPayment(false);
      fetchFinancials();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) {
      toast.error(err.response?.data?.message || 'فشلت عملية الدفع');
    } finally {
      setSubmittingPayment(false);
    }
  };

  const statusMap: Record<string, { label: string; cls: string }> = {
    DRAFT: { label: 'مسودة', cls: 'status-pending' },
    ISSUED: { label: 'صادرة', cls: 'status-active' },
    PARTIALLY_PAID: { label: 'مدفوعة جزئياً', cls: 'status-pending' },
    PAID: { label: 'مدفوعة', cls: 'status-completed' },
    CANCELLED: { label: 'ملغاة', cls: 'status-cancelled' },
  };

  return (
    <div className="portal-page">
      <div className="portal-page-header">
        <h1><CreditCard size={28}/> الفواتير والمدفوعات</h1>
      </div>

      {balance && (
        <div className="portal-balance-card">
          <div>
            <span>الرصيد المستحق</span>
            <h2>{balance.totalOutstanding?.toFixed(3)} {balance.currency}</h2>
          </div>
          <span>{balance.invoiceCount} فواتير</span>
        </div>
      )}

      {/* Payment Modal */}
      {showPayment && selectedInvoice && (
        <div className="portal-modal-overlay">
          <div className="portal-modal" style={{ maxWidth: '400px' }}>
            <div className="portal-modal-header">
              <h2>دفع الفاتورة</h2>
              <button onClick={() => setShowPayment(false)}><X size={20} /></button>
            </div>
            <form onSubmit={handlePay} className="portal-form">
              <div className="portal-input-group">
                <label>رقم الفاتورة</label>
                <input type="text" value={`#${selectedInvoice.id}`} disabled />
              </div>
              <div className="portal-input-group">
                <label>المبلغ المراد دفعه</label>
                <input 
                  type="number" 
                  step="0.001"
                  max={Number(selectedInvoice.totalAmount) - Number(selectedInvoice.paidAmount)}
                  value={paymentAmount}
                  onChange={e => setPaymentAmount(e.target.value)}
                  required 
                />
              </div>
              <div className="portal-input-group">
                <label>طريقة الدفع</label>
                <select value={paymentMethod} onChange={e => setPaymentMethod(e.target.value)}>
                  <option value="CREDIT_CARD">بطاقة ائتمان (Credit Card)</option>
                  <option value="WALLET">محفظة إلكترونية (E-Wallet)</option>
                </select>
              </div>
              <button type="submit" className="portal-submit-btn mt-4" disabled={submittingPayment}>
                {submittingPayment ? <Loader2 className="animate-spin" size={18} /> : 'دفع الآن'}
              </button>
            </form>
          </div>
        </div>
      )}

      {loading ? (
        <div className="portal-page-loader"><Loader2 className="animate-spin" size={30}/></div>
      ) : invoices.length === 0 ? (
        <div className="portal-empty"><CreditCard size={48}/><p>لا توجد فواتير</p></div>
      ) : (
        <div className="portal-list">
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          {invoices.map((inv: any) => {
            const st = statusMap[inv.status] || { label: inv.status, cls: '' };
            const canPay = ['ISSUED', 'PARTIALLY_PAID'].includes(inv.status);

            return (
              <div key={inv.id} className="portal-list-item">
                <div className="portal-list-item-content">
                  <div className="portal-list-item-top">
                    <span className={`portal-status ${st.cls}`}>{st.label}</span>
                    <span className="portal-list-date">{new Date(inv.createdAt).toLocaleDateString('ar-LY')}</span>
                  </div>
                  <div className="portal-invoice-amounts">
                    <span>الإجمالي: <strong>{Number(inv.totalAmount).toFixed(3)} {inv.currency}</strong></span>
                    <span>المدفوع: <strong>{Number(inv.paidAmount).toFixed(3)} {inv.currency}</strong></span>
                  </div>
                </div>
                {canPay && (
                  <button className="portal-primary-btn" style={{ padding: '0.5rem 1rem' }} onClick={() => openPaymentModal(inv)}>
                    دفع الآن
                  </button>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

/**
 * Patient Portal — Medical Records Page
 * 
 * Tabbed view of: Vitals, Lab Results, Medications, Allergies, Diagnoses, Encounters
 */

import { useEffect, useState } from 'react';
import { portalApi } from '../../api/portalApi';
import { FileText, Activity, FlaskConical, Pill, AlertTriangle, Stethoscope, Loader2, Download } from 'lucide-react';
import { toast } from 'sonner';

type Tab = 'vitals' | 'labs' | 'medications' | 'allergies' | 'diagnoses' | 'encounters';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const tabs: { key: Tab; label: string; icon: any }[] = [
  { key: 'vitals', label: 'العلامات الحيوية', icon: Activity },
  { key: 'labs', label: 'نتائج التحاليل', icon: FlaskConical },
  { key: 'medications', label: 'الأدوية', icon: Pill },
  { key: 'allergies', label: 'الحساسية', icon: AlertTriangle },
  { key: 'diagnoses', label: 'التشخيصات', icon: Stethoscope },
  { key: 'encounters', label: 'الزيارات', icon: FileText },
];

export default function PortalMedicalRecords() {
  const [activeTab, setActiveTab] = useState<Tab>('vitals');
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const endpoints: Record<Tab, string> = {
    vitals: '/medical/vitals',
    labs: '/medical/lab-results',
    medications: '/medical/medications',
    allergies: '/medical/allergies',
    diagnoses: '/medical/diagnoses',
    encounters: '/medical/encounters',
  };

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setLoading(true);
    portalApi.get(endpoints[activeTab])
      .then(res => setData(res.data?.items || res.data || []))
      .catch(() => {})
      .finally(() => setLoading(false));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab]);

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const handleDownloadPdf = (item: any) => {
    // Simulated PDF Download using print window
    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      toast.error('يرجى السماح بالنوافذ المنبثقة (Pop-ups)');
      return;
    }

    printWindow.document.write(`
      <html dir="rtl" lang="ar">
        <head>
          <title>نتيجة تحليل - ${item.test?.name || 'تحليل'}</title>
          <style>
            body { font-family: 'Tajawal', system-ui, sans-serif; padding: 40px; color: #333; }
            .header { text-align: center; border-bottom: 2px solid #2B5E7D; padding-bottom: 20px; margin-bottom: 30px; }
            .header h1 { color: #2B5E7D; margin: 0; }
            .info-table { width: 100%; margin-bottom: 30px; border-collapse: collapse; }
            .info-table td { padding: 10px; border: 1px solid #ddd; }
            .info-table td.label { font-weight: bold; background-color: #f9fafb; width: 30%; }
            .result-box { padding: 20px; border: 1px solid #2B5E7D; border-radius: 8px; background-color: #f0f7fb; }
            .footer { margin-top: 50px; text-align: center; font-size: 12px; color: #666; }
          </style>
        </head>
        <body>
          <div class="header">
            <h1>مستشفى السرايا التخصصي</h1>
            <h2>تقرير نتيجة تحليل طبي</h2>
          </div>
          <table class="info-table">
            <tr><td class="label">اسم التحليل</td><td>${item.test?.name || 'غير محدد'}</td></tr>
            <tr><td class="label">تاريخ النتيجة</td><td>${new Date(item.createdAt).toLocaleDateString('ar-LY')}</td></tr>
            <tr><td class="label">حالة النتيجة</td><td>${item.resultStatus === 'FINAL' ? 'نهائية' : 'مبدئية'}</td></tr>
          </table>
          <div class="result-box">
            <h3 style="margin-top:0">النتيجة:</h3>
            <p>${item.resultValue || 'تم إرفاق النتيجة في النظام.'}</p>
            ${item.referenceRange ? `<p><small>المعدل الطبيعي: ${item.referenceRange}</small></p>` : ''}
            ${item.notes ? `<p><strong>ملاحظات:</strong> ${item.notes}</p>` : ''}
          </div>
          <div class="footer">
            <p>هذا التقرير صادر إلكترونياً من بوابة المريض - نظام السرايا الطبي</p>
          </div>
          <script>
            window.onload = function() { window.print(); window.close(); }
          </script>
        </body>
      </html>
    `);
    printWindow.document.close();
  };

  return (
    <div className="portal-page">
      <div className="portal-page-header">
        <h1><FileText size={28} /> السجلات الطبية</h1>
      </div>

      {/* Tabs */}
      <div className="portal-tabs">
        {tabs.map(tab => (
          <button
            key={tab.key}
            className={`portal-tab ${activeTab === tab.key ? 'active' : ''}`}
            onClick={() => setActiveTab(tab.key)}
          >
            <tab.icon size={16} />
            {tab.label}
          </button>
        ))}
      </div>

      {/* Content */}
      {loading ? (
        <div className="portal-page-loader"><Loader2 className="animate-spin" size={30} /></div>
      ) : data.length === 0 ? (
        <div className="portal-empty">
          <FileText size={48} />
          <p>لا توجد سجلات</p>
        </div>
      ) : (
        <div className="portal-list">
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          {data.map((item: any, i: number) => (
            <div key={item.id || i} className="portal-list-item">
              <div className="portal-list-item-content">
                {activeTab === 'vitals' && (
                  <>
                    <div className="portal-list-item-top">
                      <span className="portal-list-date">{new Date(item.createdAt).toLocaleDateString('ar-LY')}</span>
                    </div>
                    <div className="portal-vitals-grid">
                      {item.temperature && <span>🌡 {item.temperature}°C</span>}
                      {item.heartRate && <span>❤️ {item.heartRate} bpm</span>}
                      {item.bpSystolic && <span>🩸 {item.bpSystolic}/{item.bpDiastolic}</span>}
                      {item.o2Saturation && <span>💨 {item.o2Saturation}%</span>}
                    </div>
                  </>
                )}
                {activeTab === 'labs' && (
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', width: '100%' }}>
                    <div>
                      <h4>{item.test?.name || 'تحليل'}</h4>
                      <p className="portal-card-sub">{item.resultStatus === 'FINAL' ? 'نتيجة نهائية' : 'مبدئية'}</p>
                    </div>
                    {item.resultStatus === 'FINAL' && (
                      <button 
                        className="portal-secondary-btn" 
                        style={{ padding: '0.4rem 0.8rem', fontSize: '0.9rem' }}
                        onClick={() => handleDownloadPdf(item)}
                      >
                        <Download size={16} /> تحميل PDF
                      </button>
                    )}
                  </div>
                )}
                {activeTab === 'medications' && (
                  <>
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    <h4>{item.items?.map((i: any) => i.product?.name).join(', ') || 'وصفة'}</h4>
                    <p className="portal-card-sub">
                      د. {item.doctor?.fullName} — {new Date(item.createdAt).toLocaleDateString('ar-LY')}
                    </p>
                    <span className={`portal-status ${item.status === 'ACTIVE' ? 'status-active' : 'status-completed'}`}>
                      {item.status === 'ACTIVE' ? 'نشطة' : 'منتهية'}
                    </span>
                  </>
                )}
                {activeTab === 'allergies' && (
                  <>
                    <h4>{item.allergen}</h4>
                    <span className={`portal-tag ${item.severity === 'HIGH' ? 'danger' : 'warning'}`}>
                      {item.severity === 'HIGH' ? 'شديدة' : item.severity === 'MODERATE' ? 'متوسطة' : 'خفيفة'}
                    </span>
                    {item.reaction && <p className="portal-card-sub">{item.reaction}</p>}
                  </>
                )}
                {activeTab === 'diagnoses' && (
                  <>
                    <h4>{item.description || item.code || 'تشخيص'}</h4>
                    <p className="portal-card-sub">{new Date(item.createdAt).toLocaleDateString('ar-LY')}</p>
                  </>
                )}
                {activeTab === 'encounters' && (
                  <>
                    <div className="portal-list-item-top">
                      <span className={`portal-status ${item.status === 'OPEN' ? 'status-active' : 'status-completed'}`}>
                        {item.status === 'OPEN' ? 'مفتوحة' : item.status === 'COMPLETED' ? 'مكتملة' : item.status}
                      </span>
                      <span className="portal-list-date">{new Date(item.createdAt).toLocaleDateString('ar-LY')}</span>
                    </div>
                    <div className="portal-list-item-details">
                      {item.doctor && <span>د. {item.doctor.fullName}</span>}
                      {item.department && <span>{item.department.name}</span>}
                    </div>
                    {item.chiefComplaint && <p className="portal-list-item-note">{item.chiefComplaint}</p>}
                  </>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState, useRef } from 'react';
import { portalApi } from '../../api/portalApi';
import { toast } from 'sonner';
import { MessageSquare, Send, ArrowRight, Loader2, Plus } from 'lucide-react';

export default function PortalMessages() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [threads, setThreads] = useState<any[]>([]);
  const [selectedThread, setSelectedThread] = useState<string | null>(null);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [messages, setMessages] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [msgLoading, setMsgLoading] = useState(false);
  const [showCompose, setShowCompose] = useState(false);
  const [newMsg, setNewMsg] = useState({ doctorId: '', subject: '', body: '' });
  const [replyBody, setReplyBody] = useState('');
  const [sending, setSending] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [departments, setDepartments] = useState<any[]>([]);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [doctors, setDoctors] = useState<any[]>([]);
  const [selectedDept, setSelectedDept] = useState<number | null>(null);
  const [fetchingDir, setFetchingDir] = useState(false);

  const fetchThreads = () => {
    portalApi.get('/messages/threads')
      .then(res => setThreads(res.data?.items || res.data || []))
      .catch(() => {})
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    fetchThreads();
    const interval = setInterval(fetchThreads, 30000);
    return () => clearInterval(interval);
  }, []);

  const openThread = (threadId: string) => {
    setSelectedThread(threadId);
    setMsgLoading(true);
    portalApi.get(`/messages/${threadId}`)
      .then(res => {
        setMessages(res.data?.items || res.data || []);
        setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
      })
      .finally(() => setMsgLoading(false));
  };

  const openCompose = async () => {
    setShowCompose(true);
    setNewMsg({ doctorId: '', subject: '', body: '' });
    setSelectedDept(null);
    setDoctors([]);
    if (departments.length === 0) {
      setFetchingDir(true);
      try {
        const res = await portalApi.get('/directory/departments');
        setDepartments(res.data || []);
      } catch {
        toast.error('فشل تحميل الأقسام');
      } finally {
        setFetchingDir(false);
      }
    }
  };

  const handleDeptChange = async (deptId: number) => {
    setSelectedDept(deptId);
    setNewMsg({ ...newMsg, doctorId: '' });
    if (!deptId) {
      setDoctors([]);
      return;
    }
    setFetchingDir(true);
    try {
      const res = await portalApi.get(`/directory/doctors?departmentId=${deptId}`);
      setDoctors(res.data || []);
    } catch {
      toast.error('فشل تحميل الأطباء');
    } finally {
      setFetchingDir(false);
    }
  };

  const handleSendNew = async (e: React.FormEvent) => {
    e.preventDefault();
    setSending(true);
    try {
      await portalApi.post('/messages', { doctorId: Number(newMsg.doctorId), subject: newMsg.subject || undefined, body: newMsg.body });
      toast.success('تم إرسال الرسالة');
      setShowCompose(false);
      setNewMsg({ doctorId: '', subject: '', body: '' });
      fetchThreads();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) { toast.error(err.response?.data?.message || 'فشل الإرسال'); }
    finally { setSending(false); }
  };

  const handleReply = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!replyBody.trim() || !selectedThread) return;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const doctorId = messages.find((m: any) => m.doctorId)?.doctorId;
    if (!doctorId) return;
    setSending(true);
    try {
      await portalApi.post('/messages', { doctorId, body: replyBody, threadId: selectedThread });
      setReplyBody('');
      openThread(selectedThread);
      fetchThreads();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) { toast.error(err.response?.data?.message || 'فشل الإرسال'); }
    finally { setSending(false); }
  };

  return (
    <div className="portal-page">
      <div className="portal-page-header">
        <h1><MessageSquare size={28} /> المراسلات</h1>
        <button className="portal-primary-btn" onClick={openCompose}><Plus size={18} /> رسالة جديدة</button>
      </div>

      {showCompose && (
        <div className="portal-modal-overlay"><div className="portal-modal">
          <div className="portal-modal-header"><h2>رسالة جديدة</h2><button onClick={() => setShowCompose(false)}>✕</button></div>
          <form onSubmit={handleSendNew} className="portal-form">
            <div className="portal-input-group">
              <label>القسم</label>
              <select 
                value={selectedDept || ''} 
                onChange={e => handleDeptChange(Number(e.target.value))}
                required
              >
                <option value="">-- اختر القسم --</option>
                {departments.map(d => (
                  <option key={d.id} value={d.id}>{d.name}</option>
                ))}
              </select>
            </div>
            <div className="portal-input-group">
              <label>الطبيب</label>
              <select 
                value={newMsg.doctorId} 
                onChange={e => setNewMsg({...newMsg, doctorId: e.target.value})}
                required
                disabled={!selectedDept || fetchingDir}
              >
                <option value="">{fetchingDir ? 'جاري التحميل...' : '-- اختر الطبيب --'}</option>
                {doctors.map(d => (
                  <option key={d.id} value={d.id}>د. {d.fullName} ({d.specialty || 'عام'})</option>
                ))}
              </select>
            </div>
            <div className="portal-input-group"><label>الموضوع</label><input type="text" value={newMsg.subject} onChange={e => setNewMsg({...newMsg, subject: e.target.value})} /></div>
            <div className="portal-input-group"><label>الرسالة</label><textarea value={newMsg.body} rows={4} onChange={e => setNewMsg({...newMsg, body: e.target.value})} required /></div>
            <button type="submit" className="portal-submit-btn" disabled={sending}>{sending ? <Loader2 className="animate-spin" size={18}/> : 'إرسال'}</button>
          </form>
        </div></div>
      )}

      <div className="portal-messaging-layout">
        <div className={`portal-threads ${selectedThread ? 'hide-mobile' : ''}`}>
          {loading ? <div className="portal-page-loader"><Loader2 className="animate-spin" size={24}/></div> : threads.length === 0 ? (
            <div className="portal-empty small"><MessageSquare size={36}/><p>لا توجد محادثات</p></div>
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          ) : threads.map((t: any) => (
            <div key={t.threadId} className={`portal-thread-item ${selectedThread === t.threadId ? 'active' : ''}`} onClick={() => openThread(t.threadId)}>
              <div className="portal-thread-top"><span className="portal-thread-doctor">د. {t.doctorName}</span>{t.unreadCount > 0 && <span className="portal-badge">{t.unreadCount}</span>}</div>
              {t.subject && <p className="portal-thread-subject">{t.subject}</p>}
              <p className="portal-thread-preview">{t.body?.slice(0, 60)}...</p>
              <span className="portal-thread-time">{new Date(t.createdAt).toLocaleDateString('ar-LY', { month: 'short', day: 'numeric' })}</span>
            </div>
          ))}
        </div>

        <div className={`portal-chat ${selectedThread ? 'show' : ''}`}>
          {!selectedThread ? <div className="portal-empty"><MessageSquare size={48}/><p>اختر محادثة</p></div> : msgLoading ? <div className="portal-page-loader"><Loader2 className="animate-spin" size={24}/></div> : (
            <>
              <div className="portal-chat-header"><button className="portal-back-btn mobile-only" onClick={() => setSelectedThread(null)}><ArrowRight size={18}/> رجوع</button></div>
              <div className="portal-chat-messages">
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                {messages.map((msg: any) => (
                  <div key={msg.id} className={`portal-message ${msg.direction === 'PATIENT_TO_DOCTOR' ? 'sent' : 'received'}`}>
                    <div className="portal-message-bubble"><p>{msg.body}</p><span className="portal-message-time">{new Date(msg.createdAt).toLocaleTimeString('ar-LY', { hour: '2-digit', minute: '2-digit' })}</span></div>
                  </div>
                ))}
                <div ref={chatEndRef}/>
              </div>
              <form onSubmit={handleReply} className="portal-chat-input">
                <input type="text" value={replyBody} onChange={e => setReplyBody(e.target.value)} placeholder="اكتب رسالتك..."/>
                <button type="submit" disabled={sending || !replyBody.trim()}><Send size={18}/></button>
              </form>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { portalApi } from '../../api/portalApi';
import { User, Loader2, Shield, AlertTriangle, Phone, Mail, MapPin, Calendar, MessageCircle, CheckCircle2 } from 'lucide-react';

export default function PortalProfile() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [profile, setProfile] = useState<any>(null);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [insurance, setInsurance] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([
      portalApi.get('/medical/profile').then(r => setProfile(r.data)),
      portalApi.get('/financial/insurance').then(r => setInsurance(r.data)),
    ]).catch(() => {}).finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="portal-page-loader"><Loader2 className="animate-spin" size={40}/></div>;

  return (
    <div className="portal-page">
      <div className="portal-page-header"><h1><User size={28}/> الملف الشخصي</h1></div>

